export interface SensorReadings {
  raw: number[];        // The 11 raw integer values from serial
  normalized: number[]; // The 11 mapped values (0.0 - 1.0)
  derived: {            // Calculated additional degrees of freedom
    thumbOpposition: number;
    indexDIP: number;
    middleDIP: number;
    ringDIP: number;
    pinkyDIP: number;
  };
}

export interface CalibrationRange {
  min: number;
  max: number;
}

export interface HandCalibration {
  ranges: CalibrationRange[]; // Array of 11 ranges
  isCalibrated: boolean;
}

export enum CalibrationStep {
  IDLE = 'IDLE',
  FIST = 'FIST',       // Step 1: Clench fist (Set MAX for flexion)
  FLAT = 'FLAT',       // Step 2: Flat hand (Set MIN for flexion, MIN for spread)
  SPREAD = 'SPREAD',   // Step 3: Spread thumb (Set MAX for spread)
}

// Mapping of the 11 serial integers to logical fingers
export const SENSOR_MAP = {
  THUMB_MCP: 0,
  THUMB_IP: 1,
  INDEX_MCP: 2,
  INDEX_PIP: 3,
  MIDDLE_MCP: 4,
  MIDDLE_PIP: 5,
  RING_MCP: 6,
  RING_PIP: 7,
  PINKY_MCP: 8,
  PINKY_PIP: 9,
  THUMB_SPREAD: 10,
};

import React, { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Group, MathUtils } from 'three';
import { SensorReadings, SENSOR_MAP } from '../types';

// Helper to create a bone segment
const Bone = ({ width, length, color = "#aaaaaa" }: { width: number; length: number; color?: string }) => (
  <mesh position={[0, length / 2, 0]} castShadow receiveShadow>
    <boxGeometry args={[width, length, width * 0.85]} />
    <meshStandardMaterial color={color} roughness={0.5} metalness={0.5} />
  </mesh>
);

// Helper for joints (visual only)
const Joint = ({ size = 0.35 }: { size?: number }) => (
  <mesh position={[0, 0, 0]} castShadow receiveShadow>
    <sphereGeometry args={[size, 16, 16]} />
    <meshStandardMaterial color="#444" roughness={0.5} metalness={0.5} />
  </mesh>
);

interface HandModelProps {
  data: SensorReadings;
  manualOverride: boolean;
}

export const HandModel: React.FC<HandModelProps> = ({ data }) => {
  const groupRef = useRef<Group>(null);

  // Finger Refs
  const thumbCMCRef = useRef<Group>(null);
  const thumbMCPRef = useRef<Group>(null);
  const thumbIPRef = useRef<Group>(null);

  const indexMCPRef = useRef<Group>(null);
  const indexPIPRef = useRef<Group>(null);
  const indexDIPRef = useRef<Group>(null);

  const middleMCPRef = useRef<Group>(null);
  const middlePIPRef = useRef<Group>(null);
  const middleDIPRef = useRef<Group>(null);

  const ringMCPRef = useRef<Group>(null);
  const ringPIPRef = useRef<Group>(null);
  const ringDIPRef = useRef<Group>(null);

  const pinkyMCPRef = useRef<Group>(null);
  const pinkyPIPRef = useRef<Group>(null);
  const pinkyDIPRef = useRef<Group>(null);

  useFrame(() => {
    const { normalized, derived } = data;
    const D = normalized;
    const alpha = 0.15; 

    // --- THUMB ---
    if (thumbCMCRef.current) {
      const spreadVal = D[SENSOR_MAP.THUMB_SPREAD];
      thumbCMCRef.current.rotation.z = MathUtils.lerp(thumbCMCRef.current.rotation.z, -0.2 + (spreadVal * 0.9), alpha);
      thumbCMCRef.current.rotation.y = MathUtils.lerp(thumbCMCRef.current.rotation.y, -0.5 - (derived.thumbOpposition * 1.1), alpha);
    }

    if (thumbMCPRef.current) {
      thumbMCPRef.current.rotation.x = MathUtils.lerp(thumbMCPRef.current.rotation.x, D[SENSOR_MAP.THUMB_MCP] * Math.PI * 0.5, alpha);
    }
    if (thumbIPRef.current) {
      thumbIPRef.current.rotation.x = MathUtils.lerp(thumbIPRef.current.rotation.x, D[SENSOR_MAP.THUMB_IP] * Math.PI * 0.5, alpha);
    }

    // --- FINGERS ---
    const flexFinger = (mcpRef: React.RefObject<Group>, pipRef: React.RefObject<Group>, dipRef: React.RefObject<Group>, mcpIdx: number, pipIdx: number, dipVal: number) => {
        if (mcpRef.current) {
            mcpRef.current.rotation.x = MathUtils.lerp(mcpRef.current.rotation.x, D[mcpIdx] * Math.PI * 0.5, alpha);
        }
        if (pipRef.current) {
            pipRef.current.rotation.x = MathUtils.lerp(pipRef.current.rotation.x, D[pipIdx] * Math.PI * 0.6, alpha);
        }
        if (dipRef.current) {
            dipRef.current.rotation.x = MathUtils.lerp(dipRef.current.rotation.x, dipVal * Math.PI * 0.6, alpha);
        }
    };

    flexFinger(indexMCPRef, indexPIPRef, indexDIPRef, SENSOR_MAP.INDEX_MCP, SENSOR_MAP.INDEX_PIP, derived.indexDIP);
    flexFinger(middleMCPRef, middlePIPRef, middleDIPRef, SENSOR_MAP.MIDDLE_MCP, SENSOR_MAP.MIDDLE_PIP, derived.middleDIP);
    flexFinger(ringMCPRef, ringPIPRef, ringDIPRef, SENSOR_MAP.RING_MCP, SENSOR_MAP.RING_PIP, derived.ringDIP);
    flexFinger(pinkyMCPRef, pinkyPIPRef, pinkyDIPRef, SENSOR_MAP.PINKY_MCP, SENSOR_MAP.PINKY_PIP, derived.pinkyDIP);
  });

  return (
    <group ref={groupRef} position={[0, -2, 0]} scale={1.2}>
        {/* PALM */}
        <mesh position={[0, 1.5, 0]} castShadow receiveShadow>
            <boxGeometry args={[2.2, 2.4, 0.5]} />
            <meshStandardMaterial color="#333" roughness={0.2} metalness={0.8} />
        </mesh>

        {/* THUMB */}
        <group position={[1.2, 0.5, 0.2]} rotation={[0, 0, 0.5]} ref={thumbCMCRef}>
            <Joint />
            <group rotation={[0,0,-0.5]}>
                <Bone width={0.5} length={1.2} color="#00bcd4" />
                <group position={[0, 1.2, 0]} ref={thumbMCPRef}>
                    <Joint />
                    <Bone width={0.45} length={1.0} color="#00bcd4" />
                    <group position={[0, 1.0, 0]} ref={thumbIPRef}>
                        <Joint />
                        <Bone width={0.4} length={0.8} color="#00bcd4" />
                    </group>
                </group>
            </group>
        </group>

        {/* INDEX */}
        <group position={[0.8, 2.7, 0]} ref={indexMCPRef}>
             <Joint />
             <Bone width={0.45} length={1.2} />
             <group position={[0, 1.2, 0]} ref={indexPIPRef}>
                 <Joint />
                 <Bone width={0.4} length={1.0} />
                 <group position={[0, 1.0, 0]} ref={indexDIPRef}>
                     <Joint />
                     <Bone width={0.38} length={0.8} />
                 </group>
             </group>
        </group>

        {/* MIDDLE */}
        <group position={[0.25, 2.7, 0]} ref={middleMCPRef}>
             <Joint />
             <Bone width={0.45} length={1.4} />
             <group position={[0, 1.4, 0]} ref={middlePIPRef}>
                 <Joint />
                 <Bone width={0.4} length={1.1} />
                 <group position={[0, 1.1, 0]} ref={middleDIPRef}>
                     <Joint />
                     <Bone width={0.38} length={0.9} />
                 </group>
             </group>
        </group>

        {/* RING */}
        <group position={[-0.3, 2.7, 0]} ref={ringMCPRef}>
             <Joint />
             <Bone width={0.45} length={1.3} />
             <group position={[0, 1.3, 0]} ref={ringPIPRef}>
                 <Joint />
                 <Bone width={0.4} length={1.0} />
                 <group position={[0, 1.0, 0]} ref={ringDIPRef}>
                     <Joint />
                     <Bone width={0.38} length={0.85} />
                 </group>
             </group>
        </group>

        {/* PINKY */}
        <group position={[-0.85, 2.6, 0]} ref={pinkyMCPRef}>
             <Joint />
             <Bone width={0.42} length={1.0} />
             <group position={[0, 1.0, 0]} ref={pinkyPIPRef}>
                 <Joint />
                 <Bone width={0.38} length={0.8} />
                 <group position={[0, 0.8, 0]} ref={pinkyDIPRef}>
                     <Joint />
                     <Bone width={0.35} length={0.7} />
                 </group>
             </group>
        </group>
    </group>
  );
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, ContactShadows } from '@react-three/drei';
import { 
  Cpu, 
  Activity, 
  RefreshCw, 
  Link2, 
  Link2Off, 
  Hand, 
  CheckCircle, 
  XCircle,
  Sliders,
  Plus,
  Cable
} from 'lucide-react';
import { HandModel } from './components/HandModel';
import { serialService } from './services/serialService';
import { 
  SensorReadings, 
  HandCalibration, 
  CalibrationStep, 
  CalibrationRange, 
  SENSOR_MAP 
} from './types';

// --- Constants ---
const TOTAL_SENSORS = 11;
const INITIAL_RANGES: CalibrationRange[] = Array(TOTAL_SENSORS).fill({ min: 0, max: 4095 });

export default function App() {
  // --- State ---
  const [isConnected, setIsConnected] = useState(false);
  const [manualMode, setManualMode] = useState(false);
  const [showPanel, setShowPanel] = useState(true);

  // Serial Ports Management
  const [ports, setPorts] = useState<any[]>([]);
  const [selectedPortIndex, setSelectedPortIndex] = useState<number>(0);

  // Data
  const [rawData, setRawData] = useState<number[]>(Array(TOTAL_SENSORS).fill(0));
  const [manualData, setManualData] = useState<number[]>(Array(TOTAL_SENSORS).fill(0));
  const [manualOpposition, setManualOpposition] = useState<number>(0); 

  // New: Manual DIP values (for when manual mode is on)
  const [manualDIP, setManualDIP] = useState<{ index: number, middle: number, ring: number, pinky: number }>({
    index: 0, middle: 0, ring: 0, pinky: 0
  });

  // Calibration State
  const [calibration, setCalibration] = useState<HandCalibration>({
    ranges: INITIAL_RANGES,
    isCalibrated: false,
  });
  const [calStep, setCalStep] = useState<CalibrationStep>(CalibrationStep.IDLE);
  const [calBuffer, setCalBuffer] = useState<number[][]>([]); 

  // --- Port Management ---
  const refreshPorts = useCallback(async () => {
    const availablePorts = await serialService.getAuthorizedPorts();
    setPorts(availablePorts);
    if (selectedPortIndex >= availablePorts.length) {
      setSelectedPortIndex(Math.max(0, availablePorts.length - 1));
    }
  }, [selectedPortIndex]);

  useEffect(() => {
    refreshPorts();
    if (navigator.serial) {
      navigator.serial.addEventListener('connect', refreshPorts);
      navigator.serial.addEventListener('disconnect', refreshPorts);
    }
    return () => {
      if (navigator.serial) {
        navigator.serial.removeEventListener('connect', refreshPorts);
        navigator.serial.removeEventListener('disconnect', refreshPorts);
      }
    }
  }, [refreshPorts]);

  const handleAddPort = async () => {
    const port = await serialService.requestAccess();
    if (port) {
      await refreshPorts();
      const updatedPorts = await serialService.getAuthorizedPorts();
      const idx = updatedPorts.findIndex(p => p === port);
      if (idx !== -1) setSelectedPortIndex(idx);
    }
  };

  // --- Logic: Normalization & Derivation ---
  const processedData: SensorReadings = useMemo(() => {
    const sourceData = manualMode ? manualData : rawData;

    // 1. Normalize
    const normalized = sourceData.map((val, idx) => {
      const range = calibration.ranges[idx];
      if (range.max === range.min) return 0;
      let n = (val - range.min) / (range.max - range.min);
      n = Math.max(0, Math.min(1, n));
      return n;
    });

    // 2. Derived Calculations: Thumb Opposition
    const spreadVal = normalized[SENSOR_MAP.THUMB_SPREAD];
    const thumbMcpVal = normalized[SENSOR_MAP.THUMB_MCP];
    const calculatedOpposition = (spreadVal * 0.7) + (thumbMcpVal * 0.3); 

    // 3. Derived Calculations: Finger DIPs
    // DIP joint rotation is naturally coupled with PIP joint rotation.
    // We use a coupling factor (typically ~0.6-0.8) plus a small influence from MCP.
    const calcDIP = (pipIdx: number) => normalized[pipIdx] * 0.75;

    return {
      raw: sourceData,
      normalized,
      derived: {
        thumbOpposition: manualMode ? manualOpposition : Math.min(1, Math.max(0, calculatedOpposition)),
        indexDIP: manualMode ? manualDIP.index : calcDIP(SENSOR_MAP.INDEX_PIP),
        middleDIP: manualMode ? manualDIP.middle : calcDIP(SENSOR_MAP.MIDDLE_PIP),
        ringDIP: manualMode ? manualDIP.ring : calcDIP(SENSOR_MAP.RING_PIP),
        pinkyDIP: manualMode ? manualDIP.pinky : calcDIP(SENSOR_MAP.PINKY_PIP),
      }
    };
  }, [rawData, manualData, manualMode, calibration, manualOpposition, manualDIP]);

  // --- Serial Handler ---
  const handleSerialData = useCallback((data: number[]) => {
    if (data.length < TOTAL_SENSORS) return;
    setRawData(data);
    if (calStep !== CalibrationStep.IDLE) {
      setCalBuffer(prev => [...prev, data]);
    }
  }, [calStep]);

  const handleConnectionToggle = async () => {
    if (isConnected) {
      await serialService.disconnect();
      setIsConnected(false);
    } else {
      if (ports.length > 0 && ports[selectedPortIndex]) {
        const success = await serialService.connectToPort(ports[selectedPortIndex], handleSerialData);
        setIsConnected(success);
      } else {
        await handleAddPort();
      }
    }
  };

  // --- Calibration Logic ---
  const startCalibration = () => {
    setCalStep(CalibrationStep.FIST);
    setCalBuffer([]);
  };

  const nextCalibrationStep = () => {
    const currentRanges = [...calibration.ranges];
    const snapshot = calBuffer.length > 0 
      ? calBuffer[0].map((_, colIndex) => calBuffer.reduce((acc, row) => acc + row[colIndex], 0) / calBuffer.length)
      : rawData;

    let newRanges = currentRanges.map(r => ({ ...r }));

    if (calStep === CalibrationStep.FIST) {
       snapshot.forEach((val, idx) => { if (idx < 10) newRanges[idx].max = val; });
       setCalStep(CalibrationStep.FLAT);
       setCalBuffer([]);
    } else if (calStep === CalibrationStep.FLAT) {
       snapshot.forEach((val, idx) => { if (idx <= 10) newRanges[idx].min = val; });
       setCalStep(CalibrationStep.SPREAD);
       setCalBuffer([]);
    } else if (calStep === CalibrationStep.SPREAD) {
       newRanges[10].max = snapshot[10];
       setCalibration({ ranges: newRanges, isCalibrated: true });
       setCalStep(CalibrationStep.IDLE);
       setCalBuffer([]);
    }
  };

  const cancelCalibration = () => {
    setCalStep(CalibrationStep.IDLE);
    setCalBuffer([]);
  };

  const updateManual = (idx: number, val: number) => {
    const n = [...manualData];
    n[idx] = val;
    setManualData(n);
  };

  const updateManualDIP = (key: keyof typeof manualDIP, val: number) => {
    setManualDIP(prev => ({ ...prev, [key]: val }));
  };

  useEffect(() => {
    setManualData(Array(TOTAL_SENSORS).fill(2048));
  }, []);

  const renderSensorControl = (label: string, idx: number) => {
    const rawVal = manualMode ? manualData[idx] : rawData[idx];
    const normVal = processedData.normalized[idx];
    return (
      <div key={idx} className="mb-2 group">
        <div className="flex justify-between text-xs mb-1 items-center">
          <span className="text-gray-400 font-medium group-hover:text-cyan-200 transition-colors">{label}</span>
          <span className="font-mono text-[10px] text-gray-500 flex gap-2">
             <span className="text-gray-600 w-8 text-right">{rawVal.toFixed(0)}</span>
             <span className="text-gray-700">|</span>
             <span className={`w-8 text-right ${manualMode ? "text-purple-400" : "text-cyan-400"}`}>
               {(normVal * 100).toFixed(0)}%
             </span>
          </span>
        </div>
        {manualMode ? (
           <input type="range" min={calibration.ranges[idx].min} max={calibration.ranges[idx].max} value={manualData[idx]}
             onChange={(e) => updateManual(idx, parseInt(e.target.value))}
             className="w-full h-1.5 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-500" />
        ) : (
          <div className="w-full bg-gray-800 h-1.5 rounded-full overflow-hidden border border-gray-700/50">
            <div className="h-full bg-cyan-500 transition-all duration-200" style={{ width: `${normVal * 100}%` }} />
          </div>
        )}
      </div>
    );
  };

  const renderDIPControl = (label: string, key: keyof typeof manualDIP) => {
    const val = processedData.derived[`${key}DIP` as keyof typeof processedData.derived];
    return (
      <div className="mb-2 group">
        <div className="flex justify-between text-xs mb-1 items-center">
          <span className="text-purple-400/80 font-medium group-hover:text-purple-300 transition-colors">{label}</span>
          <span className="font-mono text-[10px] font-bold text-purple-400">{(val * 100).toFixed(0)}%</span>
        </div>
        {manualMode ? (
           <input type="range" min="0" max="1" step="0.01" value={manualDIP[key]}
             onChange={(e) => updateManualDIP(key, parseFloat(e.target.value))}
             className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
        ) : (
          <div className="w-full bg-gray-800/50 h-1 rounded-full overflow-hidden">
            <div className="h-full bg-purple-500/60" style={{ width: `${val * 100}%` }} />
          </div>
        )}
      </div>
    );
  };

  const getPortLabel = (port: any, index: number) => {
    const info = port.getInfo();
    const vid = info.usbVendorId?.toString(16).padStart(4, '0').toUpperCase();
    const pid = info.usbProductId?.toString(16).padStart(4, '0').toUpperCase();
    return vid ? `Device ${index + 1} (ID ${vid}:${pid})` : `Serial Device ${index + 1}`;
  };

  return (
    <div className="h-screen w-screen bg-gray-950 flex flex-col overflow-hidden text-gray-100 font-sans">
      <header className="h-14 border-b border-gray-800 flex items-center justify-between px-4 bg-gray-900/90 backdrop-blur z-50">
        <div className="flex items-center gap-3">
          <Cpu className="w-5 h-5 text-cyan-450" />
          <div className="flex items-baseline gap-2">
            <h1 className="font-bold text-lg tracking-tight text-gray-100">Lyokinn <span className="text-cyan-450">流金智感</span></h1>
            <span className="text-[10px] text-gray-500 font-mono border border-gray-700 px-1.5 rounded">V0.1</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
           <div className={`flex items-center gap-2 px-3 py-1 rounded-md border transition-colors ${isConnected ? 'border-green-500/30 bg-green-500/10 text-green-400' : 'border-red-500/30 bg-red-500/10 text-red-400'}`}>
              {isConnected ? <Link2 size={14} /> : <Link2Off size={14} />}
              <span className="text-xs font-medium hidden sm:inline">{isConnected ? '已连接' : '未连接'}</span>
           </div>
           <div className="flex items-center bg-gray-800 rounded-md border border-gray-700 p-0.5">
             <div className="relative border-r border-gray-700 px-2 max-w-[120px] sm:max-w-[200px]">
               <Cable size={14} className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 pointer-events-none" />
               <select value={selectedPortIndex} onChange={(e) => setSelectedPortIndex(Number(e.target.value))} disabled={isConnected}
                 className="w-full bg-transparent text-xs text-gray-300 py-1.5 pl-7 pr-2 outline-none appearance-none">
                 {ports.length === 0 && <option value={0}>未授权设备...</option>}
                 {ports.map((port, idx) => ( <option key={idx} value={idx}>{getPortLabel(port, idx)}</option> ))}
               </select>
             </div>
             <button onClick={handleAddPort} disabled={isConnected} className="p-1.5 hover:bg-gray-700 text-gray-400 hover:text-cyan-400 disabled:opacity-30"><Plus size={14} /></button>
           </div>
           <button onClick={handleConnectionToggle} className={`px-3 py-1.5 rounded text-xs font-medium border ${isConnected ? 'bg-red-900/20 text-red-400 border-red-800' : 'bg-cyan-600 text-white border-cyan-700'}`}>
             {isConnected ? '断开' : '连接'}
           </button>
           <button onClick={() => setShowPanel(!showPanel)} className={`p-1.5 rounded ${showPanel ? 'bg-cyan-900/30 text-cyan-400' : 'bg-gray-800 text-gray-400'}`}><Activity size={18} /></button>
        </div>
      </header>

      <div className="flex-1 flex relative overflow-hidden">
        <div className="flex-1 min-w-0 relative bg-gray-900">
           <Canvas shadows camera={{ position: [0, 1, 8], fov: 45 }}>
             <fog attach="fog" args={['#0d1117', 10, 60]} />
             <ambientLight intensity={1.5} />
             <directionalLight position={[10, 10, 10]} intensity={2.5} castShadow />
             <directionalLight position={[-10, 5, 5]} intensity={1.2} />
             <Environment preset="city" />
             <HandModel data={processedData} manualOverride={manualMode} />
             <ContactShadows position={[0, -2, 0]} opacity={0.6} scale={10} blur={1.5} far={4} color="#000000" />
             <Grid args={[30, 30]} cellSize={0.5} cellThickness={0.5} sectionSize={3} fadeDistance={50} sectionColor="#00e5ff" cellColor="#1a202c" position={[0, -2, 0]} />
             <OrbitControls makeDefault minPolarAngle={0} maxPolarAngle={Math.PI / 1.8} />
           </Canvas>

           {calStep !== CalibrationStep.IDLE && (
             <div className="absolute inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                <div className="bg-gray-900 border border-gray-700 p-8 rounded-2xl max-w-md w-full text-center">
                   <RefreshCw className="w-12 h-12 text-cyan-450 animate-spin-slow mx-auto mb-6" />
                   <h2 className="text-2xl font-bold mb-2">传感器标定模式</h2>
                   <p className="text-gray-400 mb-8 text-sm">
                     {calStep === CalibrationStep.FIST && "步骤 1：用力握紧拳头，并保持稳定。"}
                     {calStep === CalibrationStep.FLAT && "步骤 2：将手掌平放，五指并拢伸直。"}
                     {calStep === CalibrationStep.SPREAD && "步骤 3：尽力张开大拇指和四指（虎口张开）。"}
                   </p>
                   <div className="flex gap-3 justify-center">
                      <button onClick={cancelCalibration} className="px-6 py-2.5 rounded-lg bg-gray-800 text-gray-300 text-sm border border-gray-700">取消</button>
                      <button onClick={nextCalibrationStep} className="px-8 py-2.5 rounded-lg bg-cyan-600 text-white font-bold text-sm">{calStep === CalibrationStep.SPREAD ? '完成标定' : '下一步'}</button>
                   </div>
                </div>
             </div>
           )}
        </div>

        {showPanel && (
          <div className="w-80 md:w-96 bg-gray-900 border-l border-gray-800 flex flex-col h-full z-20 shadow-2xl overflow-hidden">
            <div className="p-4 border-b border-gray-800 flex items-center justify-between">
               <span className="text-xs font-bold uppercase text-gray-500 flex items-center gap-2"><Sliders size={14} /> 控制源设置</span>
               <div className="flex bg-gray-800 rounded-md p-1 border border-gray-700">
                  <button onClick={() => setManualMode(false)} className={`px-3 py-1 text-xs font-medium rounded ${!manualMode ? 'bg-cyan-600 text-white' : 'text-gray-400'}`}>传感器</button>
                  <button onClick={() => setManualMode(true)} className={`px-3 py-1 text-xs font-medium rounded ${manualMode ? 'bg-purple-600 text-white' : 'text-gray-400'}`}>手动</button>
               </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-6">
               <div className={`rounded-xl p-4 border ${calibration.isCalibrated ? 'bg-green-900/10 border-green-900/30' : 'bg-gray-800/40 border-gray-700/50'}`}>
                  <div className="flex items-center justify-between mb-2">
                    <h3 className="text-sm font-semibold">系统标定状态</h3>
                    {calibration.isCalibrated ? <CheckCircle className="text-green-500 w-4 h-4" /> : <XCircle className="text-orange-500 w-4 h-4" />}
                  </div>
                  <button onClick={startCalibration} className="w-full py-2 text-xs uppercase font-bold rounded-lg border bg-gray-800 text-gray-300 border-gray-600 mt-2">重新标定</button>
               </div>

               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800 flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full bg-cyan-500"></span>
                    <h3 className="text-xs font-bold text-gray-300 uppercase">拇指数据 (Thumb)</h3>
                  </div>
                  <div className="p-4 space-y-4">
                     <div>
                        <div className="flex justify-between text-xs mb-1">
                           <span className="text-purple-400 font-medium">拇指对掌 Opposition</span>
                           <span className="font-mono text-purple-400 font-bold">{(processedData.derived.thumbOpposition * 100).toFixed(1)}%</span>
                        </div>
                        {manualMode ? (
                           <input type="range" min="0" max="1" step="0.01" value={manualOpposition} onChange={(e) => setManualOpposition(parseFloat(e.target.value))}
                             className="w-full h-1.5 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-500" />
                        ) : (
                           <div className="w-full bg-gray-800 h-1.5 rounded-full overflow-hidden">
                             <div className="h-full bg-gradient-to-r from-purple-600 to-purple-400" style={{ width: `${processedData.derived.thumbOpposition * 100}%` }} />
                           </div>
                        )}
                     </div>
                     <div className="w-full h-px bg-gray-800" />
                     {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.THUMB_MCP)}
                     {renderSensorControl("指间关节 (IP)", SENSOR_MAP.THUMB_IP)}
                     {renderSensorControl("虎口张开 (Spread)", SENSOR_MAP.THUMB_SPREAD)}
                  </div>
               </div>

               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800 flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full bg-gray-500"></span>
                    <h3 className="text-xs font-bold text-gray-300 uppercase">四指数据 (Fingers)</h3>
                  </div>
                  <div className="p-4 space-y-6">
                     {/* Index */}
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">食指 (Index)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.INDEX_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.INDEX_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "index")}
                     </div>
                     {/* Middle */}
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">中指 (Middle)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.MIDDLE_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.MIDDLE_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "middle")}
                     </div>
                     {/* Ring */}
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">无名指 (Ring)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.RING_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.RING_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "ring")}
                     </div>
                     {/* Pinky */}
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">小指 (Pinky)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.PINKY_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.PINKY_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "pinky")}
                     </div>
                  </div>
               </div>
            </div>

            <div className="px-4 py-3 border-t border-gray-800 bg-gray-900 text-[10px] text-gray-600 flex justify-between">
                <span>协议: 11ch CSV @ 115200</span>
                <span>V0.1</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, ContactShadows } from '@react-three/drei';
import { 
  Cpu, 
  Activity, 
  RefreshCw, 
  Link2, 
  Link2Off, 
  Hand, 
  CheckCircle, 
  XCircle,
  Sliders,
  Plus,
  Cable
} from 'lucide-react';
import { HandModel } from './components/HandModel';
import { serialService } from './services/serialService';
import { 
  SensorReadings, 
  HandCalibration, 
  CalibrationStep, 
  CalibrationRange, 
  SENSOR_MAP 
} from './types';

// --- Constants ---
const TOTAL_SENSORS = 11;
const INITIAL_RANGES: CalibrationRange[] = Array(TOTAL_SENSORS).fill({ min: 0, max: 4095 });

export default function App() {
  // --- State ---
  const [isConnected, setIsConnected] = useState(false);
  const [manualMode, setManualMode] = useState(false);
  const [showPanel, setShowPanel] = useState(true);

  // Serial Ports Management
  const [ports, setPorts] = useState<any[]>([]);
  const [selectedPortIndex, setSelectedPortIndex] = useState<number>(0);

  // Data
  const [rawData, setRawData] = useState<number[]>(Array(TOTAL_SENSORS).fill(0));
  const [manualData, setManualData] = useState<number[]>(Array(TOTAL_SENSORS).fill(0));
  const [manualOpposition, setManualOpposition] = useState<number>(0); 

  // New: Manual DIP values (for when manual mode is on)
  const [manualDIP, setManualDIP] = useState<{ index: number, middle: number, ring: number, pinky: number }>({
    index: 0, middle: 0, ring: 0, pinky: 0
  });

  // Calibration State
  const [calibration, setCalibration] = useState<HandCalibration>({
    ranges: INITIAL_RANGES,
    isCalibrated: false,
  });
  const [calStep, setCalStep] = useState<CalibrationStep>(CalibrationStep.IDLE);
  const [calBuffer, setCalBuffer] = useState<number[][]>([]); 

  // --- Port Management ---
  const refreshPorts = useCallback(async () => {
    const availablePorts = await serialService.getAuthorizedPorts();
    setPorts(availablePorts);
    if (selectedPortIndex >= availablePorts.length) {
      setSelectedPortIndex(Math.max(0, availablePorts.length - 1));
    }
  }, [selectedPortIndex]);

  useEffect(() => {
    refreshPorts();
    if (navigator.serial) {
      navigator.serial.addEventListener('connect', refreshPorts);
      navigator.serial.addEventListener('disconnect', refreshPorts);
    }
    return () => {
      if (navigator.serial) {
        navigator.serial.removeEventListener('connect', refreshPorts);
        navigator.serial.removeEventListener('disconnect', refreshPorts);
      }
    }
  }, [refreshPorts]);

  const handleAddPort = async () => {
    const port = await serialService.requestAccess();
    if (port) {
      await refreshPorts();
      const updatedPorts = await serialService.getAuthorizedPorts();
      const idx = updatedPorts.findIndex(p => p === port);
      if (idx !== -1) setSelectedPortIndex(idx);
    }
  };

  // --- Logic: Normalization & Derivation ---
  const processedData: SensorReadings = useMemo(() => {
    const sourceData = manualMode ? manualData : rawData;

    // 1. Normalize
    const normalized = sourceData.map((val, idx) => {
      const range = calibration.ranges[idx];
      if (range.max === range.min) return 0;
      let n = (val - range.min) / (range.max - range.min);
      n = Math.max(0, Math.min(1, n));
      return n;
    });

    // 2. Derived Calculations: Thumb Opposition
    const spreadVal = normalized[SENSOR_MAP.THUMB_SPREAD];
    const thumbMcpVal = normalized[SENSOR_MAP.THUMB_MCP];
    const calculatedOpposition = (spreadVal * 0.7) + (thumbMcpVal * 0.3); 

    // 3. Derived Calculations: Finger DIPs
    // DIP joint rotation is naturally coupled with PIP joint rotation.
    // We use a coupling factor (typically ~0.6-0.8) plus a small influence from MCP.
    const calcDIP = (pipIdx: number) => normalized[pipIdx] * 0.75;

    return {
      raw: sourceData,
      normalized,
      derived: {
        thumbOpposition: manualMode ? manualOpposition : Math.min(1, Math.max(0, calculatedOpposition)),
        indexDIP: manualMode ? manualDIP.index : calcDIP(SENSOR_MAP.INDEX_PIP),
        middleDIP: manualMode ? manualDIP.middle : calcDIP(SENSOR_MAP.MIDDLE_PIP),
        ringDIP: manualMode ? manualDIP.ring : calcDIP(SENSOR_MAP.RING_PIP),
        pinkyDIP: manualMode ? manualDIP.pinky : calcDIP(SENSOR_MAP.PINKY_PIP),
      }
    };
  }, [rawData, manualData, manualMode, calibration, manualOpposition, manualDIP]);

  // --- Serial Handler ---
  const handleSerialData = useCallback((data: number[]) => {
    if (data.length < TOTAL_SENSORS) return;
    setRawData(data);
    if (calStep !== CalibrationStep.IDLE) {
      setCalBuffer(prev => [...prev, data]);
    }
  }, [calStep]);

  const handleConnectionToggle = async () => {
    if (isConnected) {
      await serialService.disconnect();
      setIsConnected(false);
    } else {
      if (ports.length > 0 && ports[selectedPortIndex]) {
        const success = await serialService.connectToPort(ports[selectedPortIndex], handleSerialData);
        setIsConnected(success);
      } else {
        await handleAddPort();
      }
    }
  };

  // --- Calibration Logic ---
  const startCalibration = () => {
    setCalStep(CalibrationStep.FIST);
    setCalBuffer([]);
  };

  const nextCalibrationStep = () => {
    const currentRanges = [...calibration.ranges];
    const snapshot = calBuffer.length > 0 
      ? calBuffer[0].map((_, colIndex) => calBuffer.reduce((acc, row) => acc + row[colIndex], 0) / calBuffer.length)
      : rawData;

    let newRanges = currentRanges.map(r => ({ ...r }));

    if (calStep === CalibrationStep.FIST) {
       snapshot.forEach((val, idx) => { if (idx < 10) newRanges[idx].max = val; });
       setCalStep(CalibrationStep.FLAT);
       setCalBuffer([]);
    } else if (calStep === CalibrationStep.FLAT) {
       snapshot.forEach((val, idx) => { if (idx <= 10) newRanges[idx].min = val; });
       setCalStep(CalibrationStep.SPREAD);
       setCalBuffer([]);
    } else if (calStep === CalibrationStep.SPREAD) {
       newRanges[10].max = snapshot[10];
       setCalibration({ ranges: newRanges, isCalibrated: true });
       setCalStep(CalibrationStep.IDLE);
       setCalBuffer([]);
    }
  };

  const cancelCalibration = () => {
    setCalStep(CalibrationStep.IDLE);
    setCalBuffer([]);
  };

  const updateManual = (idx: number, val: number) => {
    const n = [...manualData];
    n[idx] = val;
    setManualData(n);
  };

  const updateManualDIP = (key: keyof typeof manualDIP, val: number) => {
    setManualDIP(prev => ({ ...prev, [key]: val }));
  };

  useEffect(() => {
    setManualData(Array(TOTAL_SENSORS).fill(2048));
  }, []);

  const renderSensorControl = (label: string, idx: number) => {
    const rawVal = manualMode ? manualData[idx] : rawData[idx];
    const normVal = processedData.normalized[idx];
    return (
      <div key={idx} className="mb-2 group">
        <div className="flex justify-between text-xs mb-1 items-center">
          <span className="text-gray-400 font-medium group-hover:text-cyan-200 transition-colors">{label}</span>
          <span className="font-mono text-[10px] text-gray-500 flex gap-2">
             <span className="text-gray-600 w-8 text-right">{rawVal.toFixed(0)}</span>
             <span className="text-gray-700">|</span>
             <span className={`w-8 text-right ${manualMode ? "text-purple-400" : "text-cyan-400"}`}>
               {(normVal * 100).toFixed(0)}%
             </span>
          </span>
        </div>
        {manualMode ? (
           <input type="range" min={calibration.ranges[idx].min} max={calibration.ranges[idx].max} value={manualData[idx]}
             onChange={(e) => updateManual(idx, parseInt(e.target.value))}
             className="w-full h-1.5 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-500" />
        ) : (
          <div className="w-full bg-gray-800 h-1.5 rounded-full overflow-hidden border border-gray-700/50">
            <div className="h-full bg-cyan-500 transition-all duration-200" style={{ width: `${normVal * 100}%` }} />
          </div>
        )}
      </div>
    );
  };

  const renderDIPControl = (label: string, key: keyof typeof manualDIP) => {
    // Add String(key) to avoid implicit symbol-to-string conversion error in template literal (Fix for line 229-230 reporting)
    const val = processedData.derived[`${String(key)}DIP` as keyof typeof processedData.derived];
    return (
      <div className="mb-2 group">
        <div className="flex justify-between text-xs mb-1 items-center">
          <span className="text-purple-400/80 font-medium group-hover:text-purple-300 transition-colors">{label}</span>
          <span className="font-mono text-[10px] font-bold text-purple-400">{(val * 100).toFixed(0)}%</span>
        </div>
        {manualMode ? (
           <input type="range" min="0" max="1" step="0.01" value={manualDIP[key]}
             onChange={(e) => updateManualDIP(key, parseFloat(e.target.value))}
             className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
        ) : (
          <div className="w-full bg-gray-800/50 h-1 rounded-full overflow-hidden">
            <div className="h-full bg-purple-500/60" style={{ width: `${val * 100}%` }} />
          </div>
        )}
      </div>
    );
  };

  const getPortLabel = (port: any, index: number) => {
    const info = port.getInfo();
    const vid = info.usbVendorId?.toString(16).padStart(4, '0').toUpperCase();
    const pid = info.usbProductId?.toString(16).padStart(4, '0').toUpperCase();
    return vid ? `Device ${index + 1} (ID ${vid}:${pid})` : `Serial Device ${index + 1}`;
  };

  return (
    <div className="h-screen w-screen bg-gray-950 flex flex-col overflow-hidden text-gray-100 font-sans">
      <header className="h-14 border-b border-gray-800 flex items-center justify-between px-4 bg-gray-900/90 backdrop-blur z-50">
        <div className="flex items-center gap-3">
          <Cpu className="w-5 h-5 text-cyan-450" />
          <div className="flex items-baseline gap-2">
            <h1 className="font-bold text-lg tracking-tight text-gray-100">Lyokinn <span className="text-cyan-450">流金智感</span></h1>
            <span className="text-[10px] text-gray-500 font-mono border border-gray-700 px-1.5 rounded">V0.1</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
           <div className={`flex items-center gap-2 px-3 py-1 rounded-md border transition-colors ${isConnected ? 'border-green-500/30 bg-green-500/10 text-green-400' : 'border-red-500/30 bg-red-500/10 text-red-400'}`}>
              {isConnected ? <Link2 size={14} /> : <Link2Off size={14} />}
              <span className="text-xs font-medium hidden sm:inline">{isConnected ? '已连接' : '未连接'}</span>
           </div>
           <div className="flex items-center bg-gray-800 rounded-md border border-gray-700 p-0.5">
             <div className="relative border-r border-gray-700 px-2 max-w-[120px] sm:max-w-[200px]">
               <Cable size={14} className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 pointer-events-none" />
               <select value={selectedPortIndex} onChange={(e) => setSelectedPortIndex(Number(e.target.value))} disabled={isConnected}
                 className="w-full bg-transparent text-xs text-gray-300 py-1.5 pl-7 pr-2 outline-none appearance-none">
                 {ports.length === 0 && <option value={0}>未授权设备...</option>}
                 {ports.map((port, idx) => ( <option key={idx} value={idx}>{getPortLabel(port, idx)}</option> ))}
               </select>
             </div>
             <button onClick={handleAddPort} disabled={isConnected} className="p-1.5 hover:bg-gray-700 text-gray-400 hover:text-cyan-400 disabled:opacity-30"><Plus size={14} /></button>
           </div>
           <button onClick={handleConnectionToggle} className={`px-3 py-1.5 rounded text-xs font-medium border ${isConnected ? 'bg-red-900/20 text-red-400 border-red-800' : 'bg-cyan-600 text-white border-cyan-700'}`}>
             {isConnected ? '断开' : '连接'}
           </button>
           <button onClick={() => setShowPanel(!showPanel)} className={`p-1.5 rounded ${showPanel ? 'bg-cyan-900/30 text-cyan-400' : 'bg-gray-800 text-gray-400'}`}><Activity size={18} /></button>
        </div>
      </header>

      <div className="flex-1 flex relative overflow-hidden">
        <div className="flex-1 min-w-0 relative bg-gray-900">
           <Canvas shadows camera={{ position: [0, 1, 8], fov: 45 }}>
             <fog attach="fog" args={['#0d1117', 10, 60]} />
             <ambientLight intensity={1.5} />
             <directionalLight position={[10, 10, 10]} intensity={2.5} castShadow />
             <directionalLight position={[-10, 5, 5]} intensity={1.2} />
             <Environment preset="city" />
             <HandModel data={processedData} manualOverride={manualMode} />
             <ContactShadows position={[0, -2, 0]} opacity={0.6} scale={10} blur={1.5} far={4} color="#000000" />
             <Grid args={[30, 30]} cellSize={0.5} cellThickness={0.5} sectionSize={3} fadeDistance={50} sectionColor="#00e5ff" cellColor="#1a202c" position={[0, -2, 0]} />
             <OrbitControls makeDefault minPolarAngle={0} maxPolarAngle={Math.PI / 1.8} />
           </Canvas>

           {calStep !== CalibrationStep.IDLE && (
             <div className="absolute inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                <div className="bg-gray-900 border border-gray-700 p-8 rounded-2xl max-w-md w-full text-center">
                   <RefreshCw className="w-12 h-12 text-cyan-450 animate-spin-slow mx-auto mb-6" />
                   <h2 className="text-2xl font-bold mb-2">传感器标定模式</h2>
                   <p className="text-gray-400 mb-8 text-sm">
                     {calStep === CalibrationStep.FIST && "步骤 1：用力握紧拳头，并保持稳定。"}
                     {calStep === CalibrationStep.FLAT && "步骤 2：将手掌平放，五指并拢伸直。"}
                     {calStep === CalibrationStep.SPREAD && "步骤 3：尽力张开大拇指和四指（虎口张开）。"}
                   </p>
                   <div className="flex gap-3 justify-center">
                      <button onClick={cancelCalibration} className="px-6 py-2.5 rounded-lg bg-gray-800 text-gray-300 text-sm border border-gray-700">取消</button>
                      <button onClick={nextCalibrationStep} className="px-8 py-2.5 rounded-lg bg-cyan-600 text-white font-bold text-sm">{calStep === CalibrationStep.SPREAD ? '完成标定' : '下一步'}</button>
                   </div>
                </div>
             </div>
           )}
        </div>

        {showPanel && (
          <div className="w-80 md:w-96 bg-gray-900 border-l border-gray-800 flex flex-col h-full z-20 shadow-2xl overflow-hidden">
            <div className="p-4 border-b border-gray-800 flex items-center justify-between">
               <span className="text-xs font-bold uppercase text-gray-500 flex items-center gap-2"><Sliders size={14} /> 控制源设置</span>
               <div className="flex bg-gray-800 rounded-md p-1 border border-gray-700">
                  <button onClick={() => setManualMode(false)} className={`px-3 py-1 text-xs font-medium rounded ${!manualMode ? 'bg-cyan-600 text-white' : 'text-gray-400'}`}>传感器</button>
                  <button onClick={() => setManualMode(true)} className={`px-3 py-1 text-xs font-medium rounded ${manualMode ? 'bg-purple-600 text-white' : 'text-gray-400'}`}>手动</button>
               </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-6">
               <div className={`rounded-xl p-4 border ${calibration.isCalibrated ? 'bg-green-900/10 border-green-900/30' : 'bg-gray-800/40 border-gray-700/50'}`}>
                  <div className="flex items-center justify-between mb-2">
                    <h3 className="text-sm font-semibold">系统标定状态</h3>
                    {calibration.isCalibrated ? <CheckCircle className="text-green-500 w-4 h-4" /> : <XCircle className="text-orange-500 w-4 h-4" />}
                  </div>
                  <button onClick={startCalibration} className="w-full py-2 text-xs uppercase font-bold rounded-lg border bg-gray-800 text-gray-300 border-gray-600 mt-2">重新标定</button>
               </div>

               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800 flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full bg-cyan-500"></span>
                    <h3 className="text-xs font-bold text-gray-300 uppercase">拇指数据 (Thumb)</h3>
                  </div>
                  <div className="p-4 space-y-4">
                     <div>
                        <div className="flex justify-between text-xs mb-1">
                           <span className="text-purple-400 font-medium">拇指对掌 Opposition</span>
                           <span className="font-mono text-purple-400 font-bold">{(processedData.derived.thumbOpposition * 100).toFixed(1)}%</span>
                        </div>
                        {manualMode ? (
                           <input type="range" min="0" max="1" step="0.01" value={manualOpposition} onChange={(e) => setManualOpposition(parseFloat(e.target.value))}
                             className="w-full h-1.5 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-500" />
                        ) : (
                           <div className="w-full bg-gray-800 h-1.5 rounded-full overflow-hidden">
                             <div className="h-full bg-gradient-to-r from-purple-600 to-purple-400" style={{ width: `${processedData.derived.thumbOpposition * 100}%` }} />
                           </div>
                        )}
                     </div>
                     <div className="w-full h-px bg-gray-800" />
                     {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.THUMB_MCP)}
                     {renderSensorControl("指间关节 (IP)", SENSOR_MAP.THUMB_IP)}
                     {renderSensorControl("虎口张开 (Spread)", SENSOR_MAP.THUMB_SPREAD)}
                  </div>
               </div>

               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800 flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full bg-gray-500"></span>
                    <h3 className="text-xs font-bold text-gray-300 uppercase">四指数据 (Fingers)</h3>
                  </div>
                  <div className="p-4 space-y-6">
                     {/* Index */}
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">食指 (Index)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.INDEX_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.INDEX_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "index")}
                     </div>
                     {/* Middle */}
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">中指 (Middle)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.MIDDLE_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.MIDDLE_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "middle")}
                     </div>
                     {/* Ring */}
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">无名指 (Ring)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.RING_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.RING_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "ring")}
                     </div>
                     {/* Pinky */}
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">小指 (Pinky)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.PINKY_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.PINKY_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "pinky")}
                     </div>
                  </div>
               </div>
            </div>

            <div className="px-4 py-3 border-t border-gray-800 bg-gray-900 text-[10px] text-gray-600 flex justify-between">
                <span>协议: 11ch CSV @ 115200</span>
                <span>V0.1</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export type HandSide = 'LEFT' | 'RIGHT';

export interface SensorReadings {
  raw: number[];        // The 11 raw integer values from serial
  normalized: number[]; // The 11 mapped values (0.0 - 1.0)
  derived: {            // Calculated additional degrees of freedom
    thumbOpposition: number;
    indexDIP: number;
    middleDIP: number;
    ringDIP: number;
    pinkyDIP: number;
  };
}

export interface CalibrationRange {
  min: number;
  max: number;
}

export interface HandCalibration {
  ranges: CalibrationRange[]; // Array of 11 ranges
  isCalibrated: boolean;
}

export enum CalibrationStep {
  IDLE = 'IDLE',
  FIST = 'FIST',       // Step 1: Clench fist (Set MAX for flexion)
  FLAT = 'FLAT',       // Step 2: Flat hand (Set MIN for flexion, MIN for spread)
  SPREAD = 'SPREAD',   // Step 3: Spread thumb (Set MAX for spread)
}

// Mapping of the 11 serial integers to logical fingers
export const SENSOR_MAP = {
  THUMB_MCP: 0,
  THUMB_IP: 1,
  INDEX_MCP: 2,
  INDEX_PIP: 3,
  MIDDLE_MCP: 4,
  MIDDLE_PIP: 5,
  RING_MCP: 6,
  RING_PIP: 7,
  PINKY_MCP: 8,
  PINKY_PIP: 9,
  THUMB_SPREAD: 10,
};

import { HandSide } from '../types';

interface SerialPort {
  readable: ReadableStream<Uint8Array> | null;
  writable: WritableStream<Uint8Array> | null;
  open(options: { baudRate: number }): Promise<void>;
  close(): Promise<void>;
  getInfo(): { usbVendorId?: number; usbProductId?: number };
}

declare global {
  interface Navigator {
    serial: {
      requestPort(options?: { filters?: Array<{ usbVendorId?: number; usbProductId?: number }> }): Promise<SerialPort>;
      getPorts(): Promise<SerialPort[]>;
      addEventListener(type: string, listener: (event: Event) => void): void;
      removeEventListener(type: string, listener: (event: Event) => void): void;
    };
  }
}

export class SerialService {
  private ports: Map<HandSide, SerialPort> = new Map();
  private readers: Map<HandSide, ReadableStreamDefaultReader<string>> = new Map();
  private callbacks: Map<HandSide, (data: number[]) => void> = new Map();

  constructor() {}

  async getAuthorizedPorts(): Promise<SerialPort[]> {
    if (!navigator.serial) return [];
    return await navigator.serial.getPorts();
  }

  async requestAccess(): Promise<SerialPort | null> {
    if (!navigator.serial) throw new Error('Web Serial API not supported');
    try {
      return await navigator.serial.requestPort();
    } catch (error) {
      console.log('User cancelled port request', error);
      return null;
    }
  }

  async connectToPort(side: HandSide, port: SerialPort, onData: (data: number[]) => void): Promise<boolean> {
    if (!port) return false;
    try {
      await port.open({ baudRate: 115200 });
      this.ports.set(side, port);
      this.callbacks.set(side, onData);
      this.readLoop(side);
      return true;
    } catch (error) {
      console.error(`Serial connection failed for ${side}:`, error);
      return false;
    }
  }

  async disconnect(side: HandSide) {
    const reader = this.readers.get(side);
    if (reader) {
      await reader.cancel();
      this.readers.delete(side);
    }
    const port = this.ports.get(side);
    if (port) {
      await port.close();
      this.ports.delete(side);
    }
    this.callbacks.delete(side);
  }

  private async readLoop(side: HandSide) {
    const port = this.ports.get(side);
    if (!port || !port.readable) return;

    const textDecoder = new TextDecoderStream();
    port.readable.pipeTo(textDecoder.writable).catch(() => {}); 

    const reader = textDecoder.readable.getReader();
    this.readers.set(side, reader);

    let buffer = '';
    try {
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        if (value) {
          buffer += value;
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';
          for (const line of lines) {
            if (line.trim()) this.parseLine(side, line.trim());
          }
        }
      }
    } catch (error) {
      console.error(`Read error for ${side}:`, error);
    } finally {
      reader.releaseLock();
    }
  }

  private parseLine(side: HandSide, line: string) {
    try {
      const parts = line.split(/[,\t\s]+/); 
      const values = parts.map(p => parseInt(p, 10)).filter(n => !isNaN(n));
      const callback = this.callbacks.get(side);
      if (values.length >= 11 && callback) {
        callback(values.slice(0, 11));
      }
    } catch (e) {
      console.warn('Parse error', e);
    }
  }
}

export const serialService = new SerialService();

import React, { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Group, MathUtils } from 'three';
import { SensorReadings, SENSOR_MAP, HandSide } from '../types';

const Bone = ({ width, length, color = "#aaaaaa" }: { width: number; length: number; color?: string }) => (
  <mesh position={[0, length / 2, 0]} castShadow receiveShadow>
    <boxGeometry args={[width, length, width * 0.85]} />
    <meshStandardMaterial color={color} roughness={0.5} metalness={0.5} />
  </mesh>
);

const Joint = ({ size = 0.35 }: { size?: number }) => (
  <mesh position={[0, 0, 0]} castShadow receiveShadow>
    <sphereGeometry args={[size, 16, 16]} />
    <meshStandardMaterial color="#444" roughness={0.5} metalness={0.5} />
  </mesh>
);

interface HandModelProps {
  data: SensorReadings;
  manualOverride: boolean;
  side: HandSide;
  position?: [number, number, number];
}

export const HandModel: React.FC<HandModelProps> = ({ data, side, position = [0, -2, 0] }) => {
  const groupRef = useRef<Group>(null);
  const mirror = side === 'LEFT' ? -1 : 1;

  // Finger Refs
  const thumbCMCRef = useRef<Group>(null);
  const thumbMCPRef = useRef<Group>(null);
  const thumbIPRef = useRef<Group>(null);

  const indexMCPRef = useRef<Group>(null);
  const indexPIPRef = useRef<Group>(null);
  const indexDIPRef = useRef<Group>(null);

  const middleMCPRef = useRef<Group>(null);
  const middlePIPRef = useRef<Group>(null);
  const middleDIPRef = useRef<Group>(null);

  const ringMCPRef = useRef<Group>(null);
  const ringPIPRef = useRef<Group>(null);
  const ringDIPRef = useRef<Group>(null);

  const pinkyMCPRef = useRef<Group>(null);
  const pinkyPIPRef = useRef<Group>(null);
  const pinkyDIPRef = useRef<Group>(null);

  useFrame(() => {
    const { normalized, derived } = data;
    const D = normalized;
    const alpha = 0.15; 

    // --- THUMB ---
    if (thumbCMCRef.current) {
      const spreadVal = D[SENSOR_MAP.THUMB_SPREAD];
      // Flip Z and Y rotation for Left Hand
      thumbCMCRef.current.rotation.z = MathUtils.lerp(thumbCMCRef.current.rotation.z, (-0.2 + (spreadVal * 0.9)) * mirror, alpha);
      thumbCMCRef.current.rotation.y = MathUtils.lerp(thumbCMCRef.current.rotation.y, (-0.5 - (derived.thumbOpposition * 1.1)) * mirror, alpha);
    }

    if (thumbMCPRef.current) {
      thumbMCPRef.current.rotation.x = MathUtils.lerp(thumbMCPRef.current.rotation.x, D[SENSOR_MAP.THUMB_MCP] * Math.PI * 0.5, alpha);
    }
    if (thumbIPRef.current) {
      thumbIPRef.current.rotation.x = MathUtils.lerp(thumbIPRef.current.rotation.x, D[SENSOR_MAP.THUMB_IP] * Math.PI * 0.5, alpha);
    }

    // --- FINGERS ---
    const flexFinger = (mcpRef: React.RefObject<Group>, pipRef: React.RefObject<Group>, dipRef: React.RefObject<Group>, mcpIdx: number, pipIdx: number, dipVal: number) => {
        if (mcpRef.current) {
            mcpRef.current.rotation.x = MathUtils.lerp(mcpRef.current.rotation.x, D[mcpIdx] * Math.PI * 0.5, alpha);
        }
        if (pipRef.current) {
            pipRef.current.rotation.x = MathUtils.lerp(pipRef.current.rotation.x, D[pipIdx] * Math.PI * 0.6, alpha);
        }
        if (dipRef.current) {
            dipRef.current.rotation.x = MathUtils.lerp(dipRef.current.rotation.x, dipVal * Math.PI * 0.6, alpha);
        }
    };

    flexFinger(indexMCPRef, indexPIPRef, indexDIPRef, SENSOR_MAP.INDEX_MCP, SENSOR_MAP.INDEX_PIP, derived.indexDIP);
    flexFinger(middleMCPRef, middlePIPRef, middleDIPRef, SENSOR_MAP.MIDDLE_MCP, SENSOR_MAP.MIDDLE_PIP, derived.middleDIP);
    flexFinger(ringMCPRef, ringPIPRef, ringDIPRef, SENSOR_MAP.RING_MCP, SENSOR_MAP.RING_PIP, derived.ringDIP);
    flexFinger(pinkyMCPRef, pinkyPIPRef, pinkyDIPRef, SENSOR_MAP.PINKY_MCP, SENSOR_MAP.PINKY_PIP, derived.pinkyDIP);
  });

  return (
    <group ref={groupRef} position={position} scale={[1.2 * mirror, 1.2, 1.2]}>
        {/* PALM */}
        <mesh position={[0, 1.5, 0]} castShadow receiveShadow>
            <boxGeometry args={[2.2, 2.4, 0.5]} />
            <meshStandardMaterial color="#333" roughness={0.2} metalness={0.8} />
        </mesh>

        {/* THUMB */}
        <group position={[1.2, 0.5, 0.2]} rotation={[0, 0, 0.5]} ref={thumbCMCRef}>
            <Joint />
            <group rotation={[0,0,-0.5]}>
                <Bone width={0.5} length={1.2} color="#00bcd4" />
                <group position={[0, 1.2, 0]} ref={thumbMCPRef}>
                    <Joint />
                    <Bone width={0.45} length={1.0} color="#00bcd4" />
                    <group position={[0, 1.0, 0]} ref={thumbIPRef}>
                        <Joint />
                        <Bone width={0.4} length={0.8} color="#00bcd4" />
                    </group>
                </group>
            </group>
        </group>

        {/* INDEX */}
        <group position={[0.8, 2.7, 0]} ref={indexMCPRef}>
             <Joint />
             <Bone width={0.45} length={1.2} />
             <group position={[0, 1.2, 0]} ref={indexPIPRef}>
                 <Joint />
                 <Bone width={0.4} length={1.0} />
                 <group position={[0, 1.0, 0]} ref={indexDIPRef}>
                     <Joint />
                     <Bone width={0.38} length={0.8} />
                 </group>
             </group>
        </group>

        {/* MIDDLE */}
        <group position={[0.25, 2.7, 0]} ref={middleMCPRef}>
             <Joint />
             <Bone width={0.45} length={1.4} />
             <group position={[0, 1.4, 0]} ref={middlePIPRef}>
                 <Joint />
                 <Bone width={0.4} length={1.1} />
                 <group position={[0, 1.1, 0]} ref={middleDIPRef}>
                     <Joint />
                     <Bone width={0.38} length={0.9} />
                 </group>
             </group>
        </group>

        {/* RING */}
        <group position={[-0.3, 2.7, 0]} ref={ringMCPRef}>
             <Joint />
             <Bone width={0.45} length={1.3} />
             <group position={[0, 1.3, 0]} ref={ringPIPRef}>
                 <Joint />
                 <Bone width={0.4} length={1.0} />
                 <group position={[0, 1.0, 0]} ref={ringDIPRef}>
                     <Joint />
                     <Bone width={0.38} length={0.85} />
                 </group>
             </group>
        </group>

        {/* PINKY */}
        <group position={[-0.85, 2.6, 0]} ref={pinkyMCPRef}>
             <Joint />
             <Bone width={0.42} length={1.0} />
             <group position={[0, 1.0, 0]} ref={pinkyPIPRef}>
                 <Joint />
                 <Bone width={0.38} length={0.8} />
                 <group position={[0, 0.8, 0]} ref={pinkyDIPRef}>
                     <Joint />
                     <Bone width={0.35} length={0.7} />
                 </group>
             </group>
        </group>
    </group>
  );
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, ContactShadows } from '@react-three/drei';
import { 
  Cpu, 
  Activity, 
  RefreshCw, 
  Link2, 
  Link2Off, 
  CheckCircle, 
  XCircle,
  Sliders,
  Plus,
  Cable,
  ArrowLeftRight
} from 'lucide-react';
import { HandModel } from './components/HandModel';
import { serialService } from './services/serialService';
import { 
  SensorReadings, 
  HandCalibration, 
  CalibrationStep, 
  CalibrationRange, 
  SENSOR_MAP,
  HandSide
} from './types';

const TOTAL_SENSORS = 11;
const INITIAL_RANGES: CalibrationRange[] = Array(TOTAL_SENSORS).fill({ min: 0, max: 4095 });

export default function App() {
  // UI State
  const [showPanel, setShowPanel] = useState(true);
  const [activeSide, setActiveSide] = useState<HandSide>('RIGHT');
  const [ports, setPorts] = useState<any[]>([]);

  // Connection State per Hand
  const [connections, setConnections] = useState<Record<HandSide, boolean>>({
    LEFT: false,
    RIGHT: false
  });
  const [selectedPortIndices, setSelectedPortIndices] = useState<Record<HandSide, number>>({
    LEFT: 0,
    RIGHT: 0
  });

  // Data per Hand
  const [rawData, setRawData] = useState<Record<HandSide, number[]>>({
    LEFT: Array(TOTAL_SENSORS).fill(0),
    RIGHT: Array(TOTAL_SENSORS).fill(0)
  });
  const [manualMode, setManualMode] = useState<Record<HandSide, boolean>>({
    LEFT: false,
    RIGHT: false
  });
  const [manualData, setManualData] = useState<Record<HandSide, number[]>>({
    LEFT: Array(TOTAL_SENSORS).fill(2048),
    RIGHT: Array(TOTAL_SENSORS).fill(2048)
  });
  const [manualOpposition, setManualOpposition] = useState<Record<HandSide, number>>({
    LEFT: 0,
    RIGHT: 0
  });
  const [manualDIP, setManualDIP] = useState<Record<HandSide, { index: number, middle: number, ring: number, pinky: number }>>({
    LEFT: { index: 0, middle: 0, ring: 0, pinky: 0 },
    RIGHT: { index: 0, middle: 0, ring: 0, pinky: 0 }
  });

  // Calibration State per Hand
  const [calibrations, setCalibrations] = useState<Record<HandSide, HandCalibration>>({
    LEFT: { ranges: INITIAL_RANGES, isCalibrated: false },
    RIGHT: { ranges: INITIAL_RANGES, isCalibrated: false }
  });
  const [calStep, setCalStep] = useState<CalibrationStep>(CalibrationStep.IDLE);
  const [calBuffer, setCalBuffer] = useState<number[][]>([]); 

  // --- Helpers ---
  const refreshPorts = useCallback(async () => {
    const availablePorts = await serialService.getAuthorizedPorts();
    setPorts(availablePorts);
  }, []);

  useEffect(() => {
    refreshPorts();
    if (navigator.serial) {
      navigator.serial.addEventListener('connect', refreshPorts);
      navigator.serial.addEventListener('disconnect', refreshPorts);
    }
    return () => {
      if (navigator.serial) {
        navigator.serial.removeEventListener('connect', refreshPorts);
        navigator.serial.removeEventListener('disconnect', refreshPorts);
      }
    }
  }, [refreshPorts]);

  const handleAddPort = async (side: HandSide) => {
    const port = await serialService.requestAccess();
    if (port) {
      await refreshPorts();
      const updatedPorts = await serialService.getAuthorizedPorts();
      const idx = updatedPorts.findIndex(p => p === port);
      if (idx !== -1) setSelectedPortIndices(prev => ({ ...prev, [side]: idx }));
    }
  };

  // --- Logic: Process Data ---
  const getProcessedData = (side: HandSide): SensorReadings => {
    const isManual = manualMode[side];
    const sourceData = isManual ? manualData[side] : rawData[side];
    const calibration = calibrations[side];

    const normalized = sourceData.map((val, idx) => {
      const range = calibration.ranges[idx];
      if (range.max === range.min) return 0;
      let n = (val - range.min) / (range.max - range.min);
      return Math.max(0, Math.min(1, n));
    });

    const spreadVal = normalized[SENSOR_MAP.THUMB_SPREAD];
    const thumbMcpVal = normalized[SENSOR_MAP.THUMB_MCP];
    const calculatedOpposition = (spreadVal * 0.7) + (thumbMcpVal * 0.3); 
    const calcDIP = (pipIdx: number) => normalized[pipIdx] * 0.75;

    return {
      raw: sourceData,
      normalized,
      derived: {
        thumbOpposition: isManual ? manualOpposition[side] : Math.min(1, Math.max(0, calculatedOpposition)),
        indexDIP: isManual ? manualDIP[side].index : calcDIP(SENSOR_MAP.INDEX_PIP),
        middleDIP: isManual ? manualDIP[side].middle : calcDIP(SENSOR_MAP.MIDDLE_PIP),
        ringDIP: isManual ? manualDIP[side].ring : calcDIP(SENSOR_MAP.RING_PIP),
        pinkyDIP: isManual ? manualDIP[side].pinky : calcDIP(SENSOR_MAP.PINKY_PIP),
      }
    };
  };

  const leftProcessed = useMemo(() => getProcessedData('LEFT'), [rawData.LEFT, manualData.LEFT, manualMode.LEFT, calibrations.LEFT, manualOpposition.LEFT, manualDIP.LEFT]);
  const rightProcessed = useMemo(() => getProcessedData('RIGHT'), [rawData.RIGHT, manualData.RIGHT, manualMode.RIGHT, calibrations.RIGHT, manualOpposition.RIGHT, manualDIP.RIGHT]);

  // --- Serial Handler ---
  const handleSerialData = (side: HandSide, data: number[]) => {
    setRawData(prev => ({ ...prev, [side]: data }));
    if (calStep !== CalibrationStep.IDLE && side === activeSide) {
      setCalBuffer(prev => [...prev, data]);
    }
  };

  const handleConnectionToggle = async (side: HandSide) => {
    if (connections[side]) {
      await serialService.disconnect(side);
      setConnections(prev => ({ ...prev, [side]: false }));
    } else {
      const port = ports[selectedPortIndices[side]];
      if (port) {
        const success = await serialService.connectToPort(side, port, (d) => handleSerialData(side, d));
        setConnections(prev => ({ ...prev, [side]: success }));
      } else {
        await handleAddPort(side);
      }
    }
  };

  // --- Calibration logic ---
  const startCalibration = () => {
    setCalStep(CalibrationStep.FIST);
    setCalBuffer([]);
  };

  const nextCalibrationStep = () => {
    const side = activeSide;
    const currentCalibration = calibrations[side];
    const snapshot = calBuffer.length > 0 
      ? calBuffer[0].map((_, colIndex) => calBuffer.reduce((acc, row) => acc + row[colIndex], 0) / calBuffer.length)
      : rawData[side];

    let newRanges = currentCalibration.ranges.map(r => ({ ...r }));

    if (calStep === CalibrationStep.FIST) {
       snapshot.forEach((val, idx) => { if (idx < 10) newRanges[idx].max = val; });
       setCalStep(CalibrationStep.FLAT);
       setCalBuffer([]);
    } else if (calStep === CalibrationStep.FLAT) {
       snapshot.forEach((val, idx) => { if (idx <= 10) newRanges[idx].min = val; });
       setCalStep(CalibrationStep.SPREAD);
       setCalBuffer([]);
    } else if (calStep === CalibrationStep.SPREAD) {
       newRanges[10].max = snapshot[10];
       setCalibrations(prev => ({ ...prev, [side]: { ranges: newRanges, isCalibrated: true } }));
       setCalStep(CalibrationStep.IDLE);
       setCalBuffer([]);
    }
  };

  // UI Handlers
  const updateManual = (idx: number, val: number) => {
    setManualData(prev => {
        const n = [...prev[activeSide]];
        n[idx] = val;
        return { ...prev, [activeSide]: n };
    });
  };

  const updateManualDIP = (key: string, val: number) => {
    setManualDIP(prev => ({
        ...prev,
        [activeSide]: { ...prev[activeSide], [key]: val }
    }));
  };

  // --- Rendering Helpers ---
  const renderSensorControl = (label: string, idx: number) => {
    const side = activeSide;
    const isManual = manualMode[side];
    const rawVal = isManual ? manualData[side][idx] : rawData[side][idx];
    const processed = side === 'LEFT' ? leftProcessed : rightProcessed;
    const normVal = processed.normalized[idx];
    const calibration = calibrations[side];

    return (
      <div key={idx} className="mb-2 group">
        <div className="flex justify-between text-xs mb-1 items-center">
          <span className="text-gray-400 font-medium group-hover:text-cyan-200 transition-colors">{label}</span>
          <span className="font-mono text-[10px] text-gray-500 flex gap-2">
             <span className="text-gray-600 w-8 text-right">{rawVal.toFixed(0)}</span>
             <span className="text-gray-700">|</span>
             <span className={`w-8 text-right ${isManual ? "text-purple-400" : "text-cyan-400"}`}>
               {(normVal * 100).toFixed(0)}%
             </span>
          </span>
        </div>
        {isManual ? (
           <input type="range" min={calibration.ranges[idx].min} max={calibration.ranges[idx].max} value={manualData[side][idx]}
             onChange={(e) => updateManual(idx, parseInt(e.target.value))}
             className="w-full h-1.5 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-500" />
        ) : (
          <div className="w-full bg-gray-800 h-1.5 rounded-full overflow-hidden border border-gray-700/50">
            <div className="h-full bg-cyan-500 transition-all duration-200" style={{ width: `${normVal * 100}%` }} />
          </div>
        )}
      </div>
    );
  };

  const renderDIPControl = (label: string, key: 'index' | 'middle' | 'ring' | 'pinky') => {
    const side = activeSide;
    const isManual = manualMode[side];
    const processed = side === 'LEFT' ? leftProcessed : rightProcessed;
    const val = processed.derived[`${key}DIP` as keyof typeof processed.derived];

    return (
      <div className="mb-2 group">
        <div className="flex justify-between text-xs mb-1 items-center">
          <span className="text-purple-400/80 font-medium group-hover:text-purple-300 transition-colors">{label}</span>
          <span className="font-mono text-[10px] font-bold text-purple-400">{(val * 100).toFixed(0)}%</span>
        </div>
        {isManual ? (
           <input type="range" min="0" max="1" step="0.01" value={manualDIP[side][key]}
             onChange={(e) => updateManualDIP(key, parseFloat(e.target.value))}
             className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
        ) : (
          <div className="w-full bg-gray-800/50 h-1 rounded-full overflow-hidden">
