const TOTAL_SENSORS = 11;
const INITIAL_RANGES: CalibrationRange[] = Array(TOTAL_SENSORS).fill({ min: 0, max: 4095 });

export default function App() {
  // UI State
  const [showPanel, setShowPanel] = useState(true);
  const [activeSide, setActiveSide] = useState<HandSide>('RIGHT');
  const [ports, setPorts] = useState<any[]>([]);

  // Connection State per Hand
  const [connections, setConnections] = useState<Record<HandSide, boolean>>({
    LEFT: false,
    RIGHT: false
  });
  const [selectedPortIndices, setSelectedPortIndices] = useState<Record<HandSide, number>>({
    LEFT: 0,
    RIGHT: 0
  });

  // Data per Hand
  const [rawData, setRawData] = useState<Record<HandSide, number[]>>({
    LEFT: Array(TOTAL_SENSORS).fill(0),
    RIGHT: Array(TOTAL_SENSORS).fill(0)
  });
  const [manualMode, setManualMode] = useState<Record<HandSide, boolean>>({
    LEFT: false,
    RIGHT: false
  });
  const [manualData, setManualData] = useState<Record<HandSide, number[]>>({
    LEFT: Array(TOTAL_SENSORS).fill(2048),
    RIGHT: Array(TOTAL_SENSORS).fill(2048)
  });
  const [manualOpposition, setManualOpposition] = useState<Record<HandSide, number>>({
    LEFT: 0,
    RIGHT: 0
  });
  const [manualDIP, setManualDIP] = useState<Record<HandSide, { index: number, middle: number, ring: number, pinky: number }>>({
    LEFT: { index: 0, middle: 0, ring: 0, pinky: 0 },
    RIGHT: { index: 0, middle: 0, ring: 0, pinky: 0 }
  });

  // Calibration State
  const [calibrations, setCalibrations] = useState<Record<HandSide, HandCalibration>>({
    LEFT: { ranges: INITIAL_RANGES, isCalibrated: false },
    RIGHT: { ranges: INITIAL_RANGES, isCalibrated: false }
  });
  const [calStep, setCalStep] = useState<CalibrationStep>(CalibrationStep.IDLE);
  const [calTarget, setCalTarget] = useState<'LEFT' | 'RIGHT' | 'BOTH'>('RIGHT');
  const [calBuffers, setCalBuffers] = useState<Record<HandSide, number[][]>>({
    LEFT: [],
    RIGHT: []
  }); 

  // --- Helpers ---
  const refreshPorts = useCallback(async () => {
    const availablePorts = await serialService.getAuthorizedPorts();
    setPorts(availablePorts);
  }, []);

  useEffect(() => {
    refreshPorts();
    if (navigator.serial) {
      navigator.serial.addEventListener('connect', refreshPorts);
      navigator.serial.addEventListener('disconnect', refreshPorts);
    }
    return () => {
      if (navigator.serial) {
        navigator.serial.removeEventListener('connect', refreshPorts);
        navigator.serial.removeEventListener('disconnect', refreshPorts);
      }
    }
  }, [refreshPorts]);

  const handleAddPort = async (side: HandSide) => {
    const port = await serialService.requestAccess();
    if (port) {
      await refreshPorts();
      const updatedPorts = await serialService.getAuthorizedPorts();
      const idx = updatedPorts.findIndex(p => p === port);
      if (idx !== -1) setSelectedPortIndices(prev => ({ ...prev, [side]: idx }));
    }
  };

  // --- Logic: Process Data ---
  const getProcessedData = useCallback((side: HandSide): SensorReadings => {
    const isManual = manualMode[side];
    const sourceData = isManual ? manualData[side] : rawData[side];
    const calibration = calibrations[side];

    const normalized = sourceData.map((val, idx) => {
      const range = calibration.ranges[idx];
      if (range.max === range.min) return 0;
      let n = (val - range.min) / (range.max - range.min);
      return Math.max(0, Math.min(1, n));
    });

    const spreadVal = normalized[SENSOR_MAP.THUMB_SPREAD];
    const thumbMcpVal = normalized[SENSOR_MAP.THUMB_MCP];
    const calculatedOpposition = (spreadVal * 0.7) + (thumbMcpVal * 0.3); 
    const calcDIP = (pipIdx: number) => normalized[pipIdx] * 0.75;

    return {
      raw: sourceData,
      normalized,
      derived: {
        thumbOpposition: isManual ? manualOpposition[side] : Math.min(1, Math.max(0, calculatedOpposition)),
        indexDIP: isManual ? manualDIP[side].index : calcDIP(SENSOR_MAP.INDEX_PIP),
        middleDIP: isManual ? manualDIP[side].middle : calcDIP(SENSOR_MAP.MIDDLE_PIP),
        ringDIP: isManual ? manualDIP[side].ring : calcDIP(SENSOR_MAP.RING_PIP),
        pinkyDIP: isManual ? manualDIP[side].pinky : calcDIP(SENSOR_MAP.PINKY_PIP),
      }
    };
  }, [rawData, manualData, manualMode, calibrations, manualOpposition, manualDIP]);

  const leftProcessed = useMemo(() => getProcessedData('LEFT'), [getProcessedData]);
  const rightProcessed = useMemo(() => getProcessedData('RIGHT'), [getProcessedData]);

  // --- Serial Handler ---
  const handleSerialData = (side: HandSide, data: number[]) => {
    setRawData(prev => ({ ...prev, [side]: data }));
    if (calStep !== CalibrationStep.IDLE) {
      if (calTarget === 'BOTH' || calTarget === side) {
        setCalBuffers(prev => ({
          ...prev,
          [side]: [...prev[side], data]
        }));
      }
    }
  };

  const handleConnectionToggle = async (side: HandSide) => {
    if (connections[side]) {
      await serialService.disconnect(side);
      setConnections(prev => ({ ...prev, [side]: false }));
    } else {
      const port = ports[selectedPortIndices[side]];
      if (port) {
        const success = await serialService.connectToPort(side, port, (d) => handleSerialData(side, d));
        setConnections(prev => ({ ...prev, [side]: success }));
      } else {
        await handleAddPort(side);
      }
    }
  };

  // --- Simultaneous Calibration Logic ---
  const startCalibration = (target: 'LEFT' | 'RIGHT' | 'BOTH') => {
    setCalTarget(target);
    setCalStep(CalibrationStep.FIST);
    setCalBuffers({ LEFT: [], RIGHT: [] });
  };

  const nextCalibrationStep = () => {
    const sidesToCalibrate: HandSide[] = calTarget === 'BOTH' ? ['LEFT', 'RIGHT'] : [calTarget];
    const updatedCalibrations = { ...calibrations };

    sidesToCalibrate.forEach(side => {
      const buffer = calBuffers[side];
      const snapshot = buffer.length > 0 
        ? buffer[0].map((_, colIndex) => buffer.reduce((acc, row) => acc + row[colIndex], 0) / buffer.length)
        : rawData[side];

      let newRanges = calibrations[side].ranges.map(r => ({ ...r }));

      if (calStep === CalibrationStep.FIST) {
         snapshot.forEach((val, idx) => { if (idx < 10) newRanges[idx].max = val; });
         updatedCalibrations[side] = { ...updatedCalibrations[side], ranges: newRanges };
      } else if (calStep === CalibrationStep.FLAT) {
         snapshot.forEach((val, idx) => { if (idx <= 10) newRanges[idx].min = val; });
         updatedCalibrations[side] = { ...updatedCalibrations[side], ranges: newRanges };
      } else if (calStep === CalibrationStep.SPREAD) {
         newRanges[10].max = snapshot[10];
         updatedCalibrations[side] = { ranges: newRanges, isCalibrated: true };
      }
    });

    setCalibrations(updatedCalibrations);

    if (calStep === CalibrationStep.FIST) {
      setCalStep(CalibrationStep.FLAT);
    } else if (calStep === CalibrationStep.FLAT) {
      setCalStep(CalibrationStep.SPREAD);
    } else {
      setCalStep(CalibrationStep.IDLE);
    }
    setCalBuffers({ LEFT: [], RIGHT: [] });
  };

  // UI Handlers
  const updateManual = (idx: number, val: number) => {
    setManualData(prev => {
        const n = [...prev[activeSide]];
        n[idx] = val;
        return { ...prev, [activeSide]: n };
    });
  };

  const updateManualDIP = (key: string, val: number) => {
    setManualDIP(prev => ({
        ...prev,
        [activeSide]: { ...prev[activeSide], [key]: val }
    }));
  };

  // --- Rendering Helpers ---
  const renderSensorControl = (label: string, idx: number) => {
    const side = activeSide;
    const isManual = manualMode[side];
    const rawVal = isManual ? manualData[side][idx] : rawData[side][idx];
    const processed = side === 'LEFT' ? leftProcessed : rightProcessed;
    const normVal = processed.normalized[idx];
    const calibration = calibrations[side];

    return (
      <div key={idx} className="mb-2 group">
        <div className="flex justify-between text-xs mb-1 items-center">
          <span className="text-gray-400 font-medium group-hover:text-cyan-200 transition-colors">{label}</span>
          <span className="font-mono text-[10px] text-gray-500 flex gap-2">
             <span className="text-gray-600 w-8 text-right">{rawVal.toFixed(0)}</span>
             <span className="text-gray-700">|</span>
             <span className={`w-8 text-right ${isManual ? "text-purple-400" : "text-cyan-400"}`}>
               {(normVal * 100).toFixed(0)}%
             </span>
          </span>
        </div>
        {isManual ? (
           <input type="range" min={calibration.ranges[idx].min} max={calibration.ranges[idx].max} value={manualData[side][idx]}
             onChange={(e) => updateManual(idx, parseInt(e.target.value))}
             className="w-full h-1.5 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-500" />
        ) : (
          <div className="w-full bg-gray-800 h-1.5 rounded-full overflow-hidden border border-gray-700/50">
            <div className="h-full bg-cyan-500 transition-all duration-200" style={{ width: `${normVal * 100}%` }} />
          </div>
        )}
      </div>
    );
  };

  const renderDIPControl = (label: string, key: 'index' | 'middle' | 'ring' | 'pinky') => {
    const side = activeSide;
    const isManual = manualMode[side];
    const processed = side === 'LEFT' ? leftProcessed : rightProcessed;
    const val = processed.derived[`${key}DIP` as keyof typeof processed.derived];

    return (
      <div className="mb-2 group">
        <div className="flex justify-between text-xs mb-1 items-center">
          <span className="text-purple-400/80 font-medium group-hover:text-purple-300 transition-colors">{label}</span>
          <span className="font-mono text-[10px] font-bold text-purple-400">{(val * 100).toFixed(0)}%</span>
        </div>
        {isManual ? (
           <input type="range" min="0" max="1" step="0.01" value={manualDIP[side][key]}
             onChange={(e) => updateManualDIP(key, parseFloat(e.target.value))}
             className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
        ) : (
          <div className="w-full bg-gray-800/50 h-1 rounded-full overflow-hidden">
            <div className="h-full bg-purple-500/60" style={{ width: `${val * 100}%` }} />
          </div>
        )}
      </div>
    );
  };

  const getPortLabel = (port: any, index: number) => {
    const info = port.getInfo();
    const vid = info.usbVendorId?.toString(16).padStart(4, '0').toUpperCase();
    const pid = info.usbProductId?.toString(16).padStart(4, '0').toUpperCase();
    return vid ? `Device ${index + 1} (ID ${vid}:${pid})` : `Serial Device ${index + 1}`;
  };

  const getGlobalStatusText = () => {
    if (connections.LEFT && connections.RIGHT) return '双手已连接';
    if (connections.LEFT) return '左手已连接';
    if (connections.RIGHT) return '右手已连接';
    return '未连接设备';
  };

  return (
    <div className="h-screen w-screen bg-gray-950 flex flex-col overflow-hidden text-gray-100 font-sans">
      <header className="h-14 border-b border-gray-800 flex items-center justify-between px-4 bg-gray-900/90 backdrop-blur z-50">
        <div className="flex items-center gap-3">
          <Cpu className="w-5 h-5 text-cyan-450" />
          <div className="flex items-baseline gap-2">
            <h1 className="font-bold text-lg tracking-tight text-gray-100">Lyokinn <span className="text-cyan-450">流金智感</span></h1>
            <span className="text-[10px] text-gray-500 font-mono border border-gray-700 px-1.5 rounded">V0.2</span>
          </div>
          <div className={`ml-4 text-[10px] font-bold px-2 py-0.5 rounded uppercase ${connections.LEFT || connections.RIGHT ? 'bg-green-500/20 text-green-400' : 'bg-red-500/20 text-red-400'}`}>
            {getGlobalStatusText()}
          </div>
        </div>

        <div className="flex items-center gap-2">
            {/* Left Hand Connection */}
            <div className="flex items-center bg-gray-800/50 rounded-md border border-gray-700/50 p-0.5 group">
                <span className="text-[10px] font-bold px-2 text-gray-500 group-hover:text-cyan-400 transition-colors">L</span>
                <select value={selectedPortIndices.LEFT} onChange={(e) => setSelectedPortIndices(p => ({ ...p, LEFT: Number(e.target.value) }))} disabled={connections.LEFT}
                    className="bg-transparent text-[10px] text-gray-400 py-1 pl-1 outline-none max-w-[80px]">
                    {ports.length === 0 && <option value={0}>No Port</option>}
                    {ports.map((p, idx) => (<option key={idx} value={idx}>{getPortLabel(p, idx).split(' ')[0]}</option>))}
                </select>
                <button onClick={() => handleConnectionToggle('LEFT')} className={`ml-1 px-2 py-1 rounded text-[10px] font-bold border ${connections.LEFT ? 'bg-red-900/30 text-red-400 border-red-800' : 'bg-cyan-600 text-white border-cyan-700'}`}>
                    {connections.LEFT ? 'OFF' : 'ON'}
                </button>
            </div>

            {/* Right Hand Connection */}
            <div className="flex items-center bg-gray-800/50 rounded-md border border-gray-700/50 p-0.5 group">
                <span className="text-[10px] font-bold px-2 text-gray-500 group-hover:text-purple-400 transition-colors">R</span>
                <select value={selectedPortIndices.RIGHT} onChange={(e) => setSelectedPortIndices(p => ({ ...p, RIGHT: Number(e.target.value) }))} disabled={connections.RIGHT}
                    className="bg-transparent text-[10px] text-gray-400 py-1 pl-1 outline-none max-w-[80px]">
                    {ports.length === 0 && <option value={0}>No Port</option>}
                    {ports.map((p, idx) => (<option key={idx} value={idx}>{getPortLabel(p, idx).split(' ')[0]}</option>))}
                </select>
                <button onClick={() => handleConnectionToggle('RIGHT')} className={`ml-1 px-2 py-1 rounded text-[10px] font-bold border ${connections.RIGHT ? 'bg-red-900/30 text-red-400 border-red-800' : 'bg-purple-600 text-white border-purple-700'}`}>
                    {connections.RIGHT ? 'OFF' : 'ON'}
                </button>
            </div>

            <button onClick={() => setShowPanel(!showPanel)} className={`p-1.5 ml-2 rounded ${showPanel ? 'bg-cyan-900/30 text-cyan-400' : 'bg-gray-800 text-gray-400'}`}><Activity size={18} /></button>
        </div>
      </header>

      <div className="flex-1 flex relative overflow-hidden">
        <div className="flex-1 min-w-0 relative bg-gray-900">
           <Canvas shadows camera={{ position: [0, 2, 12], fov: 40 }}>
             <fog attach="fog" args={['#0d1117', 10, 60]} />
             <ambientLight intensity={1.5} />
             <directionalLight position={[10, 10, 10]} intensity={2.5} castShadow />
             <directionalLight position={[-10, 5, 5]} intensity={1.2} />
             <Environment preset="city" />

             {/* Render Both Hands */}
             <HandModel data={leftProcessed} side="LEFT" position={[-3.5, -2, 0]} manualOverride={manualMode.LEFT} />
             <HandModel data={rightProcessed} side="RIGHT" position={[3.5, -2, 0]} manualOverride={manualMode.RIGHT} />

             <ContactShadows position={[0, -2, 0]} opacity={0.6} scale={15} blur={1.5} far={4} color="#000000" />
             <Grid args={[40, 40]} cellSize={0.5} cellThickness={0.5} sectionSize={3} fadeDistance={50} sectionColor="#00e5ff" cellColor="#1a202c" position={[0, -2, 0]} />
             <OrbitControls makeDefault minPolarAngle={0} maxPolarAngle={Math.PI / 1.8} />
           </Canvas>

           {calStep !== CalibrationStep.IDLE && (
             <div className="absolute inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                <div className="bg-gray-900 border border-gray-700 p-8 rounded-2xl max-w-md w-full text-center">
                   <RefreshCw className="w-12 h-12 text-cyan-450 animate-spin-slow mx-auto mb-6" />
                   <h2 className="text-2xl font-bold mb-2">传感器标定 [{calTarget === 'BOTH' ? '双侧同时' : (calTarget === 'LEFT' ? '左手' : '右手')}]</h2>
                   <div className="flex justify-center gap-4 mb-4">
                      {(calTarget === 'BOTH' || calTarget === 'LEFT') && <div className={`px-2 py-1 rounded text-[10px] font-bold border ${calBuffers.LEFT.length > 0 ? 'bg-cyan-500/20 text-cyan-400 border-cyan-500/50' : 'bg-gray-800 text-gray-600 border-gray-700'}`}>LEFT READY</div>}
                      {(calTarget === 'BOTH' || calTarget === 'RIGHT') && <div className={`px-2 py-1 rounded text-[10px] font-bold border ${calBuffers.RIGHT.length > 0 ? 'bg-purple-500/20 text-purple-400 border-purple-500/50' : 'bg-gray-800 text-gray-600 border-gray-700'}`}>RIGHT READY</div>}
                   </div>
                   <p className="text-gray-400 mb-8 text-sm h-12">
                     {calStep === CalibrationStep.FIST && `步骤 1：用力握紧${calTarget === 'BOTH' ? '双手' : ''}拳头，并保持稳定。`}
                     {calStep === CalibrationStep.FLAT && `步骤 2：将${calTarget === 'BOTH' ? '双手' : ''}手掌平放，五指并拢伸直。`}
                     {calStep === CalibrationStep.SPREAD && `步骤 3：尽力张开${calTarget === 'BOTH' ? '双手' : ''}大拇指和四指。`}
                   </p>
                   <div className="flex gap-3 justify-center">
                      <button onClick={() => setCalStep(CalibrationStep.IDLE)} className="px-6 py-2.5 rounded-lg bg-gray-800 text-gray-300 text-sm border border-gray-700">取消</button>
                      <button onClick={nextCalibrationStep} className="px-8 py-2.5 rounded-lg bg-cyan-600 text-white font-bold text-sm">{calStep === CalibrationStep.SPREAD ? '完成标定' : '下一步'}</button>
                   </div>
                </div>
             </div>
           )}
        </div>

        {showPanel && (
          <div className="w-80 md:w-96 bg-gray-900 border-l border-gray-800 flex flex-col h-full z-20 shadow-2xl overflow-hidden">
            {/* Side Switcher Tab */}
            <div className="flex bg-gray-950 p-1">
                <button onClick={() => setActiveSide('LEFT')} 
                    className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-xs font-bold transition-all rounded-t-lg ${activeSide === 'LEFT' ? 'bg-gray-900 text-cyan-400 border-t-2 border-cyan-500' : 'text-gray-600 hover:text-gray-400'}`}>
                    <ArrowLeftRight size={14} className={activeSide === 'LEFT' ? 'text-cyan-500' : ''} /> 左手 LEFT
                </button>
                <button onClick={() => setActiveSide('RIGHT')} 
                    className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-xs font-bold transition-all rounded-t-lg ${activeSide === 'RIGHT' ? 'bg-gray-900 text-purple-400 border-t-2 border-purple-500' : 'text-gray-600 hover:text-gray-400'}`}>
                    右手 RIGHT <ArrowLeftRight size={14} className={activeSide === 'RIGHT' ? 'text-purple-500' : ''} />
                </button>
            </div>

            <div className="p-4 border-b border-gray-800 flex items-center justify-between">
               <span className="text-[10px] font-bold uppercase text-gray-500 flex items-center gap-2"><Sliders size={14} /> 控制模式</span>
               <div className="flex bg-gray-800 rounded-md p-1 border border-gray-700">
                  <button onClick={() => setManualMode(prev => ({ ...prev, [activeSide]: false }))} className={`px-3 py-1 text-[10px] font-bold rounded ${!manualMode[activeSide] ? 'bg-cyan-600 text-white' : 'text-gray-400'}`}>传感器</button>
                  <button onClick={() => setManualMode(prev => ({ ...prev, [activeSide]: true }))} className={`px-3 py-1 text-[10px] font-bold rounded ${manualMode[activeSide] ? 'bg-purple-600 text-white' : 'text-gray-400'}`}>手动调节</button>
               </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-6">
               <div className={`rounded-xl p-4 border transition-colors ${calibrations[activeSide].isCalibrated ? 'bg-green-900/10 border-green-900/30' : 'bg-gray-800/40 border-gray-700/50'}`}>
                  <div className="flex items-center justify-between mb-2">
                    <h3 className="text-xs font-bold uppercase text-gray-300">标定状态 ({activeSide === 'LEFT' ? '左' : '右'})</h3>
                    {calibrations[activeSide].isCalibrated ? <CheckCircle className="text-green-500 w-4 h-4" /> : <XCircle className="text-orange-500 w-4 h-4" />}
                  </div>
                  <div className="grid grid-cols-2 gap-2 mt-2">
                    <button onClick={() => startCalibration(activeSide)} className="py-2 text-[10px] uppercase font-bold rounded-lg border bg-gray-800 text-gray-300 border-gray-600 hover:bg-gray-700 transition-colors">标定单侧</button>
                    <button 
                      onClick={() => startCalibration('BOTH')} 
                      disabled={!connections.LEFT || !connections.RIGHT}
                      className="py-2 text-[10px] uppercase font-bold rounded-lg border bg-cyan-900/40 text-cyan-300 border-cyan-800 hover:bg-cyan-900/60 transition-colors disabled:opacity-30 disabled:cursor-not-allowed">
                      双手同步标定
                    </button>
                  </div>
               </div>

               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800 flex items-center gap-2">
                    <span className={`w-2 h-2 rounded-full ${activeSide === 'LEFT' ? 'bg-cyan-500' : 'bg-purple-500'}`}></span>
                    <h3 className="text-[10px] font-bold text-gray-300 uppercase">拇指 Thumb</h3>
                  </div>
                  <div className="p-4 space-y-4">
                     <div>
                        <div className="flex justify-between text-xs mb-1">
                           <span className="text-purple-400 font-medium">拇指对掌 Opposition</span>
                           <span className="font-mono text-purple-400 font-bold">
                               {((activeSide === 'LEFT' ? leftProcessed : rightProcessed).derived.thumbOpposition * 100).toFixed(1)}%
                           </span>
                        </div>
                        {manualMode[activeSide] ? (
                           <input type="range" min="0" max="1" step="0.01" value={manualOpposition[activeSide]} onChange={(e) => {
                               const v = parseFloat(e.target.value);
                               setManualOpposition(p => ({ ...p, [activeSide]: v }));
                           }} className="w-full h-1.5 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-500" />
                        ) : (
                           <div className="w-full bg-gray-800 h-1.5 rounded-full overflow-hidden">
                             <div className="h-full bg-gradient-to-r from-purple-600 to-purple-400" style={{ width: `${(activeSide === 'LEFT' ? leftProcessed : rightProcessed).derived.thumbOpposition * 100}%` }} />
                           </div>
                        )}
                     </div>
                     <div className="w-full h-px bg-gray-800" />
                     {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.THUMB_MCP)}
                     {renderSensorControl("指间关节 (IP)", SENSOR_MAP.THUMB_IP)}
                     {renderSensorControl("虎口张开 (Spread)", SENSOR_MAP.THUMB_SPREAD)}
                  </div>
               </div>

               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800 flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full bg-gray-500"></span>
                    <h3 className="text-[10px] font-bold text-gray-300 uppercase">四指 Fingers</h3>
                  </div>
                  <div className="p-4 space-y-6">
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">食指 (Index)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.INDEX_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.INDEX_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "index")}
                     </div>
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">中指 (Middle)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.MIDDLE_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.MIDDLE_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "middle")}
                     </div>
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">无名指 (Ring)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.RING_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.RING_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "ring")}
                     </div>
                     <div className="space-y-2">
                        <div className="text-[10px] font-bold text-gray-600 uppercase border-b border-gray-800/50 pb-1">小指 (Pinky)</div>
                        {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.PINKY_MCP)}
                        {renderSensorControl("近侧指尖 (PIP)", SENSOR_MAP.PINKY_PIP)}
                        {renderDIPControl("末端指尖 (DIP)", "pinky")}
                     </div>
                  </div>
               </div>
            </div>

            <div className="px-4 py-3 border-t border-gray-800 bg-gray-900 text-[10px] text-gray-600 flex justify-between">
                <span>11ch CSV @ 115200</span>
                <span>Active: {activeSide}</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export type HandSide = 'LEFT' | 'RIGHT';

export interface SensorReadings {
  raw: number[];        // The 11 raw integer values from serial
  normalized: number[]; // The 11 mapped values (0.0 - 1.0)
  derived: {            // Calculated additional degrees of freedom
    thumbOpposition: number;
    indexDIP: number;
    middleDIP: number;
    ringDIP: number;
    pinkyDIP: number;
  };
}

export interface CalibrationRange {
  min: number;
  max: number;
  exponent: number; // For non-linear response curves (Default 1.0)
}

export interface HandCalibration {
  ranges: CalibrationRange[]; // Array of 11 ranges
  isCalibrated: boolean;
}

export enum CalibrationStep {
  IDLE = 'IDLE',
  FIST = 'FIST',       // Step 1: Clench fist (Set MAX for flexion)
  FLAT = 'FLAT',       // Step 2: Flat hand (Set MIN for flexion, MIN for spread)
  SPREAD = 'SPREAD',   // Step 3: Spread thumb (Set MAX for spread)
}

// Mapping of the 11 serial integers to logical fingers
export const SENSOR_MAP = {
  THUMB_MCP: 0,
  THUMB_IP: 1,
  INDEX_MCP: 2,
  INDEX_PIP: 3,
  MIDDLE_MCP: 4,
  MIDDLE_PIP: 5,
  RING_MCP: 6,
  RING_PIP: 7,
  PINKY_MCP: 8,
  PINKY_PIP: 9,
  THUMB_SPREAD: 10,
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, ContactShadows } from '@react-three/drei';
import { 
  Cpu, 
  Activity, 
  RefreshCw, 
  Link2, 
  Link2Off, 
  CheckCircle, 
  XCircle,
  Sliders,
  Plus,
  Cable,
  ArrowLeftRight,
  Zap
} from 'lucide-react';
import { HandModel } from './components/HandModel';
import { serialService } from './services/serialService';
import { 
  SensorReadings, 
  HandCalibration, 
  CalibrationStep, 
  CalibrationRange, 
  SENSOR_MAP,
  HandSide
} from './types';

const TOTAL_SENSORS = 11;
const INITIAL_RANGES: CalibrationRange[] = Array(TOTAL_SENSORS).fill(null).map(() => ({ 
  min: 0, 
  max: 4095, 
  exponent: 1.0 
}));

export default function App() {
  // UI State
  const [showPanel, setShowPanel] = useState(true);
  const [activeSide, setActiveSide] = useState<HandSide>('RIGHT');
  const [ports, setPorts] = useState<any[]>([]);

  // Connection State
  const [connections, setConnections] = useState<Record<HandSide, boolean>>({
    LEFT: false,
    RIGHT: false
  });
  const [selectedPortIndices, setSelectedPortIndices] = useState<Record<HandSide, number>>({
    LEFT: 0,
    RIGHT: 0
  });

  // Data per Hand
  const [rawData, setRawData] = useState<Record<HandSide, number[]>>({
    LEFT: Array(TOTAL_SENSORS).fill(0),
    RIGHT: Array(TOTAL_SENSORS).fill(0)
  });
  const [manualMode, setManualMode] = useState<Record<HandSide, boolean>>({
    LEFT: false,
    RIGHT: false
  });
  const [manualData, setManualData] = useState<Record<HandSide, number[]>>({
    LEFT: Array(TOTAL_SENSORS).fill(2048),
    RIGHT: Array(TOTAL_SENSORS).fill(2048)
  });
  const [manualOpposition, setManualOpposition] = useState<Record<HandSide, number>>({
    LEFT: 0,
    RIGHT: 0
  });
  const [manualDIP, setManualDIP] = useState<Record<HandSide, { index: number, middle: number, ring: number, pinky: number }>>({
    LEFT: { index: 0, middle: 0, ring: 0, pinky: 0 },
    RIGHT: { index: 0, middle: 0, ring: 0, pinky: 0 }
  });

  // Calibration State
  const [calibrations, setCalibrations] = useState<Record<HandSide, HandCalibration>>({
    LEFT: { ranges: INITIAL_RANGES, isCalibrated: false },
    RIGHT: { ranges: INITIAL_RANGES, isCalibrated: false }
  });
  const [calStep, setCalStep] = useState<CalibrationStep>(CalibrationStep.IDLE);
  const [calTarget, setCalTarget] = useState<'LEFT' | 'RIGHT' | 'BOTH'>('RIGHT');
  const [calBuffers, setCalBuffers] = useState<Record<HandSide, number[][]>>({
    LEFT: [],
    RIGHT: []
  }); 

  // --- Helpers ---
  const refreshPorts = useCallback(async () => {
    const availablePorts = await serialService.getAuthorizedPorts();
    setPorts(availablePorts);
  }, []);

  useEffect(() => {
    refreshPorts();
    if (navigator.serial) {
      navigator.serial.addEventListener('connect', refreshPorts);
      navigator.serial.addEventListener('disconnect', refreshPorts);
    }
    return () => {
      if (navigator.serial) {
        navigator.serial.removeEventListener('connect', refreshPorts);
        navigator.serial.removeEventListener('disconnect', refreshPorts);
      }
    }
  }, [refreshPorts]);

  const handleAddPort = async (side: HandSide) => {
    const port = await serialService.requestAccess();
    if (port) {
      await refreshPorts();
      const updatedPorts = await serialService.getAuthorizedPorts();
      const idx = updatedPorts.findIndex(p => p === port);
      if (idx !== -1) setSelectedPortIndices(prev => ({ ...prev, [side]: idx }));
    }
  };

  // --- Logic: Process Data ---
  const getProcessedData = useCallback((side: HandSide): SensorReadings => {
    const isManual = manualMode[side];
    const sourceData = isManual ? manualData[side] : rawData[side];
    const calibration = calibrations[side];

    const normalized = sourceData.map((val, idx) => {
      const range = calibration.ranges[idx];
      if (range.max === range.min) return 0;

      // 1. Linear normalization
      let n = (val - range.min) / (range.max - range.min);
      n = Math.max(0, Math.min(1, n));

      // 2. Apply curve (Gamma correction / Power Law)
      // Value = n ^ exponent
      return Math.pow(n, range.exponent);
    });

    const spreadVal = normalized[SENSOR_MAP.THUMB_SPREAD];
    const thumbMcpVal = normalized[SENSOR_MAP.THUMB_MCP];
    const calculatedOpposition = (spreadVal * 0.7) + (thumbMcpVal * 0.3); 
    const calcDIP = (pipIdx: number) => normalized[pipIdx] * 0.75;

    return {
      raw: sourceData,
      normalized,
      derived: {
        thumbOpposition: isManual ? manualOpposition[side] : Math.min(1, Math.max(0, calculatedOpposition)),
        indexDIP: isManual ? manualDIP[side].index : calcDIP(SENSOR_MAP.INDEX_PIP),
        middleDIP: isManual ? manualDIP[side].middle : calcDIP(SENSOR_MAP.MIDDLE_PIP),
        ringDIP: isManual ? manualDIP[side].ring : calcDIP(SENSOR_MAP.RING_PIP),
        pinkyDIP: isManual ? manualDIP[side].pinky : calcDIP(SENSOR_MAP.PINKY_PIP),
      }
    };
  }, [rawData, manualData, manualMode, calibrations, manualOpposition, manualDIP]);

  const leftProcessed = useMemo(() => getProcessedData('LEFT'), [getProcessedData]);
  const rightProcessed = useMemo(() => getProcessedData('RIGHT'), [getProcessedData]);

  // --- Serial Handler ---
  const handleSerialData = (side: HandSide, data: number[]) => {
    setRawData(prev => ({ ...prev, [side]: data }));
    if (calStep !== CalibrationStep.IDLE) {
      if (calTarget === 'BOTH' || calTarget === side) {
        setCalBuffers(prev => ({
          ...prev,
          [side]: [...prev[side], data]
        }));
      }
    }
  };

  const handleConnectionToggle = async (side: HandSide) => {
    if (connections[side]) {
      await serialService.disconnect(side);
      setConnections(prev => ({ ...prev, [side]: false }));
    } else {
      const port = ports[selectedPortIndices[side]];
      if (port) {
        const success = await serialService.connectToPort(side, port, (d) => handleSerialData(side, d));
        setConnections(prev => ({ ...prev, [side]: success }));
      } else {
        await handleAddPort(side);
      }
    }
  };

  // --- Calibration Logic ---
  const startCalibration = (target: 'LEFT' | 'RIGHT' | 'BOTH') => {
    setCalTarget(target);
    setCalStep(CalibrationStep.FIST);
    setCalBuffers({ LEFT: [], RIGHT: [] });
  };

  const nextCalibrationStep = () => {
    const sidesToCalibrate: HandSide[] = calTarget === 'BOTH' ? ['LEFT', 'RIGHT'] : [calTarget];
    const updatedCalibrations = { ...calibrations };

    sidesToCalibrate.forEach(side => {
      const buffer = calBuffers[side];
      const snapshot = buffer.length > 0 
        ? buffer[0].map((_, colIndex) => buffer.reduce((acc, row) => acc + row[colIndex], 0) / buffer.length)
        : rawData[side];

      let newRanges = calibrations[side].ranges.map(r => ({ ...r }));

      if (calStep === CalibrationStep.FIST) {
         snapshot.forEach((val, idx) => { if (idx < 10) newRanges[idx].max = val; });
         updatedCalibrations[side] = { ...updatedCalibrations[side], ranges: newRanges };
      } else if (calStep === CalibrationStep.FLAT) {
         snapshot.forEach((val, idx) => { if (idx <= 10) newRanges[idx].min = val; });
         updatedCalibrations[side] = { ...updatedCalibrations[side], ranges: newRanges };
      } else if (calStep === CalibrationStep.SPREAD) {
         newRanges[10].max = snapshot[10];
         updatedCalibrations[side] = { ranges: newRanges, isCalibrated: true };
      }
    });

    setCalibrations(updatedCalibrations);

    if (calStep === CalibrationStep.FIST) setCalStep(CalibrationStep.FLAT);
    else if (calStep === CalibrationStep.FLAT) setCalStep(CalibrationStep.SPREAD);
    else setCalStep(CalibrationStep.IDLE);

    setCalBuffers({ LEFT: [], RIGHT: [] });
  };

  // UI Handlers
  const updateManual = (idx: number, val: number) => {
    setManualData(prev => {
        const n = [...prev[activeSide]];
        n[idx] = val;
        return { ...prev, [activeSide]: n };
    });
  };

  const updateCurve = (idx: number, exponent: number) => {
    setCalibrations(prev => {
      const newRanges = prev[activeSide].ranges.map((r, i) => i === idx ? { ...r, exponent } : r);
      return { ...prev, [activeSide]: { ...prev[activeSide], ranges: newRanges } };
    });
  };

  // --- Rendering Helpers ---
  const renderSensorControl = (label: string, idx: number) => {
    const side = activeSide;
    const isManual = manualMode[side];
    const calibration = calibrations[side];
    const range = calibration.ranges[idx];
    const rawVal = isManual ? manualData[side][idx] : rawData[side][idx];
    const processed = side === 'LEFT' ? leftProcessed : rightProcessed;
    const normVal = processed.normalized[idx];

    return (
      <div key={idx} className="mb-4 group bg-gray-900/40 p-2 rounded-lg border border-gray-800/50">
        <div className="flex justify-between text-xs mb-1 items-center">
          <span className="text-gray-400 font-medium group-hover:text-cyan-200 transition-colors">{label}</span>
          <span className="font-mono text-[10px] text-gray-500 flex gap-2">
             <span className="text-gray-600 w-8 text-right">{rawVal.toFixed(0)}</span>
             <span className="text-gray-700">|</span>
             <span className={`w-8 text-right ${isManual ? "text-purple-400" : "text-cyan-400"}`}>
               {(normVal * 100).toFixed(0)}%
             </span>
          </span>
        </div>

        {/* Main Control Slider */}
        {isManual ? (
           <input type="range" min={range.min} max={range.max} value={manualData[side][idx]}
             onChange={(e) => updateManual(idx, parseInt(e.target.value))}
             className="w-full h-1.5 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-500 mb-2" />
        ) : (
          <div className="w-full bg-gray-800 h-1.5 rounded-full overflow-hidden border border-gray-700/50 mb-2">
            <div className="h-full bg-cyan-500 transition-all duration-200" style={{ width: `${normVal * 100}%` }} />
          </div>
        )}

        {/* Non-linear Curve Control (Always visible to allow tuning live sensors) */}
        <div className="flex items-center gap-2 mt-1 px-1">
           <Zap size={10} className={range.exponent !== 1 ? "text-yellow-500" : "text-gray-600"} />
           <input type="range" min="0.2" max="3.0" step="0.05" value={range.exponent}
             onChange={(e) => updateCurve(idx, parseFloat(e.target.value))}
             className="flex-1 h-1 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-gray-600" />
           <span className="text-[9px] font-mono text-gray-500 w-6">k={range.exponent.toFixed(1)}</span>
        </div>
      </div>
    );
  };

  const renderDIPControl = (label: string, key: 'index' | 'middle' | 'ring' | 'pinky') => {
    const side = activeSide;
    const isManual = manualMode[side];
    const processed = side === 'LEFT' ? leftProcessed : rightProcessed;
    const val = processed.derived[`${key}DIP` as keyof typeof processed.derived];

    return (
      <div className="mb-2 group px-2">
        <div className="flex justify-between text-xs mb-1 items-center">
          <span className="text-purple-400/80 font-medium group-hover:text-purple-300 transition-colors">{label}</span>
          <span className="font-mono text-[10px] font-bold text-purple-400">{(val * 100).toFixed(0)}%</span>
        </div>
        {isManual ? (
           <input type="range" min="0" max="1" step="0.01" value={manualDIP[side][key]}
             onChange={(e) => {
                setManualDIP(prev => ({ ...prev, [side]: { ...prev[side], [key]: parseFloat(e.target.value) } }));
             }}
             className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
        ) : (
          <div className="w-full bg-gray-800/50 h-1 rounded-full overflow-hidden">
            <div className="h-full bg-purple-500/60" style={{ width: `${val * 100}%` }} />
          </div>
        )}
      </div>
    );
  };

  const getPortLabel = (port: any, index: number) => {
    const info = port.getInfo();
    const vid = info.usbVendorId?.toString(16).padStart(4, '0').toUpperCase();
    const pid = info.usbProductId?.toString(16).padStart(4, '0').toUpperCase();
    return vid ? `Device ${index + 1} (ID ${vid}:${pid})` : `Serial Device ${index + 1}`;
  };

  return (
    <div className="h-screen w-screen bg-gray-950 flex flex-col overflow-hidden text-gray-100 font-sans">
      <header className="h-14 border-b border-gray-800 flex items-center justify-between px-4 bg-gray-900/90 backdrop-blur z-50">
        <div className="flex items-center gap-3">
          <Cpu className="w-5 h-5 text-cyan-450" />
          <div className="flex items-baseline gap-2">
            <h1 className="font-bold text-lg tracking-tight text-gray-100">Lyokinn <span className="text-cyan-450">流金智感</span></h1>
            <span className="text-[10px] text-gray-500 font-mono border border-gray-700 px-1.5 rounded">V0.2</span>
          </div>
          <div className={`ml-4 text-[10px] font-bold px-2 py-0.5 rounded uppercase ${connections.LEFT || connections.RIGHT ? 'bg-green-500/20 text-green-400' : 'bg-red-500/20 text-red-400'}`}>
            {connections.LEFT || connections.RIGHT ? '双手已连接' : '未连接设备'}
          </div>
        </div>

        <div className="flex items-center gap-2">
            <div className="flex items-center bg-gray-800/50 rounded-md border border-gray-700/50 p-0.5 group">
                <span className="text-[10px] font-bold px-2 text-gray-500">L</span>
                <select value={selectedPortIndices.LEFT} onChange={(e) => setSelectedPortIndices(p => ({ ...p, LEFT: Number(e.target.value) }))} disabled={connections.LEFT}
                    className="bg-transparent text-[10px] text-gray-400 py-1 pl-1 outline-none max-w-[80px]">
                    {ports.length === 0 && <option value={0}>No Port</option>}
                    {ports.map((p, idx) => (<option key={idx} value={idx}>{getPortLabel(p, idx).split(' ')[0]}</option>))}
                </select>
                <button onClick={() => handleConnectionToggle('LEFT')} className={`ml-1 px-2 py-1 rounded text-[10px] font-bold border ${connections.LEFT ? 'bg-red-900/30 text-red-400 border-red-800' : 'bg-cyan-600 text-white border-cyan-700'}`}>
                    {connections.LEFT ? 'OFF' : 'ON'}
                </button>
            </div>
            <div className="flex items-center bg-gray-800/50 rounded-md border border-gray-700/50 p-0.5 group">
                <span className="text-[10px] font-bold px-2 text-gray-500">R</span>
                <select value={selectedPortIndices.RIGHT} onChange={(e) => setSelectedPortIndices(p => ({ ...p, RIGHT: Number(e.target.value) }))} disabled={connections.RIGHT}
                    className="bg-transparent text-[10px] text-gray-400 py-1 pl-1 outline-none max-w-[80px]">
                    {ports.length === 0 && <option value={0}>No Port</option>}
                    {ports.map((p, idx) => (<option key={idx} value={idx}>{getPortLabel(p, idx).split(' ')[0]}</option>))}
                </select>
                <button onClick={() => handleConnectionToggle('RIGHT')} className={`ml-1 px-2 py-1 rounded text-[10px] font-bold border ${connections.RIGHT ? 'bg-red-900/30 text-red-400 border-red-800' : 'bg-purple-600 text-white border-purple-700'}`}>
                    {connections.RIGHT ? 'OFF' : 'ON'}
                </button>
            </div>
            <button onClick={() => setShowPanel(!showPanel)} className={`p-1.5 ml-2 rounded ${showPanel ? 'bg-cyan-900/30 text-cyan-400' : 'bg-gray-800 text-gray-400'}`}><Activity size={18} /></button>
        </div>
      </header>

      <div className="flex-1 flex relative overflow-hidden">
        <div className="flex-1 min-w-0 relative bg-gray-900">
           <Canvas shadows camera={{ position: [0, 2, 12], fov: 40 }}>
             <fog attach="fog" args={['#0d1117', 10, 60]} />
             <ambientLight intensity={1.5} />
             <directionalLight position={[10, 10, 10]} intensity={2.5} castShadow />
             <directionalLight position={[-10, 5, 5]} intensity={1.2} />
             <Environment preset="city" />
             <HandModel data={leftProcessed} side="LEFT" position={[-3.5, -2, 0]} manualOverride={manualMode.LEFT} />
             <HandModel data={rightProcessed} side="RIGHT" position={[3.5, -2, 0]} manualOverride={manualMode.RIGHT} />
             <ContactShadows position={[0, -2, 0]} opacity={0.6} scale={15} blur={1.5} far={4} color="#000000" />
             <Grid args={[40, 40]} cellSize={0.5} cellThickness={0.5} sectionSize={3} fadeDistance={50} sectionColor="#00e5ff" cellColor="#1a202c" position={[0, -2, 0]} />
             <OrbitControls makeDefault minPolarAngle={0} maxPolarAngle={Math.PI / 1.8} />
           </Canvas>

           {calStep !== CalibrationStep.IDLE && (
             <div className="absolute inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                <div className="bg-gray-900 border border-gray-700 p-8 rounded-2xl max-w-md w-full text-center">
                   <RefreshCw className="w-12 h-12 text-cyan-450 animate-spin-slow mx-auto mb-6" />
                   <h2 className="text-2xl font-bold mb-2">传感器标定 [{calTarget === 'BOTH' ? '双侧同时' : (calTarget === 'LEFT' ? '左手' : '右手')}]</h2>
                   <div className="flex justify-center gap-4 mb-4">
                      {(calTarget === 'BOTH' || calTarget === 'LEFT') && <div className={`px-2 py-1 rounded text-[10px] font-bold border ${calBuffers.LEFT.length > 0 ? 'bg-cyan-500/20 text-cyan-400 border-cyan-500/50' : 'bg-gray-800 text-gray-600 border-gray-700'}`}>LEFT READY</div>}
                      {(calTarget === 'BOTH' || calTarget === 'RIGHT') && <div className={`px-2 py-1 rounded text-[10px] font-bold border ${calBuffers.RIGHT.length > 0 ? 'bg-purple-500/20 text-purple-400 border-purple-500/50' : 'bg-gray-800 text-gray-600 border-gray-700'}`}>RIGHT READY</div>}
                   </div>
                   <p className="text-gray-400 mb-8 text-sm h-12">
                     {calStep === CalibrationStep.FIST && `步骤 1：用力握紧${calTarget === 'BOTH' ? '双手' : ''}拳头，并保持稳定。`}
                     {calStep === CalibrationStep.FLAT && `步骤 2：将${calTarget === 'BOTH' ? '双手' : ''}手掌平放，五指并拢伸直。`}
                     {calStep === CalibrationStep.SPREAD && `步骤 3：尽力张开${calTarget === 'BOTH' ? '双手' : ''}大拇指和四指。`}
                   </p>
                   <div className="flex gap-3 justify-center">
                      <button onClick={() => setCalStep(CalibrationStep.IDLE)} className="px-6 py-2.5 rounded-lg bg-gray-800 text-gray-300 text-sm border border-gray-700">取消</button>
                      <button onClick={nextCalibrationStep} className="px-8 py-2.5 rounded-lg bg-cyan-600 text-white font-bold text-sm">{calStep === CalibrationStep.SPREAD ? '完成标定' : '下一步'}</button>
                   </div>
                </div>
             </div>
           )}
        </div>

        {showPanel && (
          <div className="w-80 md:w-96 bg-gray-900 border-l border-gray-800 flex flex-col h-full z-20 shadow-2xl overflow-hidden">
            <div className="flex bg-gray-950 p-1">
                <button onClick={() => setActiveSide('LEFT')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-xs font-bold transition-all rounded-t-lg ${activeSide === 'LEFT' ? 'bg-gray-900 text-cyan-400 border-t-2 border-cyan-500' : 'text-gray-600'}`}><ArrowLeftRight size={14} /> LEFT</button>
                <button onClick={() => setActiveSide('RIGHT')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-xs font-bold transition-all rounded-t-lg ${activeSide === 'RIGHT' ? 'bg-gray-900 text-purple-400 border-t-2 border-purple-500' : 'text-gray-600'}`}>RIGHT <ArrowLeftRight size={14} /></button>
            </div>

            <div className="p-4 border-b border-gray-800 flex items-center justify-between">
               <span className="text-[10px] font-bold uppercase text-gray-500 flex items-center gap-2"><Sliders size={14} /> 控制模式</span>
               <div className="flex bg-gray-800 rounded-md p-1 border border-gray-700">
                  <button onClick={() => setManualMode(prev => ({ ...prev, [activeSide]: false }))} className={`px-3 py-1 text-[10px] font-bold rounded ${!manualMode[activeSide] ? 'bg-cyan-600 text-white' : 'text-gray-400'}`}>传感器</button>
                  <button onClick={() => setManualMode(prev => ({ ...prev, [activeSide]: true }))} className={`px-3 py-1 text-[10px] font-bold rounded ${manualMode[activeSide] ? 'bg-purple-600 text-white' : 'text-gray-400'}`}>手动</button>
               </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-6">
               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800 flex items-center justify-between">
                    <h3 className="text-[10px] font-bold text-gray-300 uppercase">响应曲线调节</h3>
                    <div className="text-[9px] text-gray-500">k &lt; 1 快发力 | k &gt; 1 慢启动</div>
                  </div>
                  <div className="p-4 bg-yellow-500/5 border-b border-yellow-500/10 mb-4">
                    <p className="text-[9px] text-yellow-500/80 leading-relaxed italic">提示：若手指还没动模型就弯了，请增大 k 值；若手指弯了很多模型才动，请减小 k 值。</p>
                  </div>
                  <div className="px-4 space-y-2">
                     {renderSensorControl("拇指弯曲", SENSOR_MAP.THUMB_MCP)}
                     {renderSensorControl("食指弯曲", SENSOR_MAP.INDEX_MCP)}
                     {renderSensorControl("中指弯曲", SENSOR_MAP.MIDDLE_MCP)}
                     {renderSensorControl("无名指弯曲", SENSOR_MAP.RING_MCP)}
                     {renderSensorControl("小指弯曲", SENSOR_MAP.PINKY_MCP)}
                  </div>
               </div>

               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800 flex items-center gap-2">
                    <h3 className="text-[10px] font-bold text-gray-300 uppercase">详细传感器快照</h3>
                  </div>
                  <div className="p-4 space-y-4">
                     {renderSensorControl("拇指指间", SENSOR_MAP.THUMB_IP)}
                     {renderSensorControl("虎口张开", SENSOR_MAP.THUMB_SPREAD)}
                     {renderSensorControl("食指 PIP", SENSOR_MAP.INDEX_PIP)}
                     {renderSensorControl("中指 PIP", SENSOR_MAP.MIDDLE_PIP)}
                     {renderSensorControl("无名指 PIP", SENSOR_MAP.RING_PIP)}
                     {renderSensorControl("小指 PIP", SENSOR_MAP.PINKY_PIP)}
                  </div>
               </div>

               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800 flex items-center gap-2">
                    <h3 className="text-[10px] font-bold text-gray-300 uppercase">末端推算 (DIP)</h3>
                  </div>
                  <div className="p-4 space-y-2">
                     {renderDIPControl("食指 DIP", "index")}
                     {renderDIPControl("中指 DIP", "middle")}
                     {renderDIPControl("无名指 DIP", "ring")}
                     {renderDIPControl("小指 DIP", "pinky")}
                  </div>
               </div>

               <div className="rounded-xl p-4 border transition-colors bg-gray-800/40 border-gray-700/50">
                  <button onClick={() => startCalibration('BOTH')} className="w-full py-3 text-[10px] uppercase font-bold rounded-lg bg-cyan-600 text-white shadow-lg shadow-cyan-900/20">重新开始引导标定</button>
               </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, ContactShadows } from '@react-three/drei';
import { 
  Cpu, 
  Activity, 
  RefreshCw, 
  CheckCircle, 
  XCircle,
  Sliders,
  ArrowLeftRight,
  Zap,
  Info
} from 'lucide-react';
import { HandModel } from './components/HandModel';
import { serialService } from './services/serialService';
import { 
  SensorReadings, 
  HandCalibration, 
  CalibrationStep, 
  CalibrationRange, 
  SENSOR_MAP,
  HandSide
} from './types';

const TOTAL_SENSORS = 11;
const INITIAL_RANGES: CalibrationRange[] = Array(TOTAL_SENSORS).fill(null).map(() => ({ 
  min: 0, 
  max: 4095, 
  exponent: 1.0 
}));

export default function App() {
  // UI State
  const [showPanel, setShowPanel] = useState(true);
  const [activeSide, setActiveSide] = useState<HandSide>('RIGHT');
  const [ports, setPorts] = useState<any[]>([]);

  // Connection State
  const [connections, setConnections] = useState<Record<HandSide, boolean>>({
    LEFT: false,
    RIGHT: false
  });
  const [selectedPortIndices, setSelectedPortIndices] = useState<Record<HandSide, number>>({
    LEFT: 0,
    RIGHT: 0
  });

  // Data per Hand
  const [rawData, setRawData] = useState<Record<HandSide, number[]>>({
    LEFT: Array(TOTAL_SENSORS).fill(0),
    RIGHT: Array(TOTAL_SENSORS).fill(0)
  });
  const [manualMode, setManualMode] = useState<Record<HandSide, boolean>>({
    LEFT: false,
    RIGHT: false
  });
  const [manualData, setManualData] = useState<Record<HandSide, number[]>>({
    LEFT: Array(TOTAL_SENSORS).fill(2048),
    RIGHT: Array(TOTAL_SENSORS).fill(2048)
  });
  const [manualOpposition, setManualOpposition] = useState<Record<HandSide, number>>({
    LEFT: 0,
    RIGHT: 0
  });
  const [manualDIP, setManualDIP] = useState<Record<HandSide, { index: number, middle: number, ring: number, pinky: number }>>({
    LEFT: { index: 0, middle: 0, ring: 0, pinky: 0 },
    RIGHT: { index: 0, middle: 0, ring: 0, pinky: 0 }
  });

  // Calibration State
  const [calibrations, setCalibrations] = useState<Record<HandSide, HandCalibration>>({
    LEFT: { ranges: INITIAL_RANGES, isCalibrated: false },
    RIGHT: { ranges: INITIAL_RANGES, isCalibrated: false }
  });
  const [calStep, setCalStep] = useState<CalibrationStep>(CalibrationStep.IDLE);
  const [calTarget, setCalTarget] = useState<'LEFT' | 'RIGHT' | 'BOTH'>('RIGHT');
  const [calBuffers, setCalBuffers] = useState<Record<HandSide, number[][]>>({
    LEFT: [],
    RIGHT: []
  }); 

  // --- Helpers ---
  const refreshPorts = useCallback(async () => {
    const availablePorts = await serialService.getAuthorizedPorts();
    setPorts(availablePorts);
  }, []);

  useEffect(() => {
    refreshPorts();
    if (navigator.serial) {
      navigator.serial.addEventListener('connect', refreshPorts);
      navigator.serial.addEventListener('disconnect', refreshPorts);
    }
    return () => {
      if (navigator.serial) {
        navigator.serial.removeEventListener('connect', refreshPorts);
        navigator.serial.removeEventListener('disconnect', refreshPorts);
      }
    }
  }, [refreshPorts]);

  const handleAddPort = async (side: HandSide) => {
    const port = await serialService.requestAccess();
    if (port) {
      await refreshPorts();
      const updatedPorts = await serialService.getAuthorizedPorts();
      const idx = updatedPorts.findIndex(p => p === port);
      if (idx !== -1) setSelectedPortIndices(prev => ({ ...prev, [side]: idx }));
    }
  };

  // --- Logic: Process Data ---
  const getProcessedData = useCallback((side: HandSide): SensorReadings => {
    const isManual = manualMode[side];
    const sourceData = isManual ? manualData[side] : rawData[side];
    const calibration = calibrations[side];

    const normalized = sourceData.map((val, idx) => {
      const range = calibration.ranges[idx];
      if (range.max === range.min) return 0;
      let n = (val - range.min) / (range.max - range.min);
      n = Math.max(0, Math.min(1, n));
      return Math.pow(n, range.exponent);
    });

    const spreadVal = normalized[SENSOR_MAP.THUMB_SPREAD];
    const thumbMcpVal = normalized[SENSOR_MAP.THUMB_MCP];
    const calculatedOpposition = (spreadVal * 0.7) + (thumbMcpVal * 0.3); 
    const calcDIP = (pipIdx: number) => normalized[pipIdx] * 0.75;

    return {
      raw: sourceData,
      normalized,
      derived: {
        thumbOpposition: isManual ? manualOpposition[side] : Math.min(1, Math.max(0, calculatedOpposition)),
        indexDIP: isManual ? manualDIP[side].index : calcDIP(SENSOR_MAP.INDEX_PIP),
        middleDIP: isManual ? manualDIP[side].middle : calcDIP(SENSOR_MAP.MIDDLE_PIP),
        ringDIP: isManual ? manualDIP[side].ring : calcDIP(SENSOR_MAP.RING_PIP),
        pinkyDIP: isManual ? manualDIP[side].pinky : calcDIP(SENSOR_MAP.PINKY_PIP),
      }
    };
  }, [rawData, manualData, manualMode, calibrations, manualOpposition, manualDIP]);

  const leftProcessed = useMemo(() => getProcessedData('LEFT'), [getProcessedData]);
  const rightProcessed = useMemo(() => getProcessedData('RIGHT'), [getProcessedData]);

  // --- Serial Handler ---
  const handleSerialData = (side: HandSide, data: number[]) => {
    setRawData(prev => ({ ...prev, [side]: data }));
    if (calStep !== CalibrationStep.IDLE) {
      if (calTarget === 'BOTH' || calTarget === side) {
        setCalBuffers(prev => ({
          ...prev,
          [side]: [...prev[side], data]
        }));
      }
    }
  };

  const handleConnectionToggle = async (side: HandSide) => {
    if (connections[side]) {
      await serialService.disconnect(side);
      setConnections(prev => ({ ...prev, [side]: false }));
    } else {
      const port = ports[selectedPortIndices[side]];
      if (port) {
        const success = await serialService.connectToPort(side, port, (d) => handleSerialData(side, d));
        setConnections(prev => ({ ...prev, [side]: success }));
      } else {
        await handleAddPort(side);
      }
    }
  };

  // --- Calibration Logic ---
  const startCalibration = (target: 'LEFT' | 'RIGHT' | 'BOTH') => {
    setCalTarget(target);
    setCalStep(CalibrationStep.FIST);
    setCalBuffers({ LEFT: [], RIGHT: [] });
  };

  const nextCalibrationStep = () => {
    const sidesToCalibrate: HandSide[] = calTarget === 'BOTH' ? ['LEFT', 'RIGHT'] : [calTarget];
    const updatedCalibrations = { ...calibrations };

    sidesToCalibrate.forEach(side => {
      const buffer = calBuffers[side];
      const snapshot = buffer.length > 0 
        ? buffer[0].map((_, colIndex) => buffer.reduce((acc, row) => acc + row[colIndex], 0) / buffer.length)
        : rawData[side];

      let newRanges = calibrations[side].ranges.map(r => ({ ...r }));

      if (calStep === CalibrationStep.FIST) {
         snapshot.forEach((val, idx) => { if (idx < 10) newRanges[idx].max = val; });
         updatedCalibrations[side] = { ...updatedCalibrations[side], ranges: newRanges };
      } else if (calStep === CalibrationStep.FLAT) {
         snapshot.forEach((val, idx) => { if (idx <= 10) newRanges[idx].min = val; });
         updatedCalibrations[side] = { ...updatedCalibrations[side], ranges: newRanges };
      } else if (calStep === CalibrationStep.SPREAD) {
         newRanges[10].max = snapshot[10];
         updatedCalibrations[side] = { ranges: newRanges, isCalibrated: true };
      }
    });

    setCalibrations(updatedCalibrations);
    if (calStep === CalibrationStep.FIST) setCalStep(CalibrationStep.FLAT);
    else if (calStep === CalibrationStep.FLAT) setCalStep(CalibrationStep.SPREAD);
    else setCalStep(CalibrationStep.IDLE);
    setCalBuffers({ LEFT: [], RIGHT: [] });
  };

  // UI Handlers
  const updateManual = (idx: number, val: number) => {
    setManualData(prev => {
        const n = [...prev[activeSide]];
        n[idx] = val;
        return { ...prev, [activeSide]: n };
    });
  };

  const updateCurve = (idx: number, exponent: number) => {
    setCalibrations(prev => {
      const newRanges = prev[activeSide].ranges.map((r, i) => i === idx ? { ...r, exponent } : r);
      return { ...prev, [activeSide]: { ...prev[activeSide], ranges: newRanges } };
    });
  };

  // --- Rendering Helpers ---
  const renderSensorControl = (label: string, idx: number) => {
    const side = activeSide;
    const isManual = manualMode[side];
    const calibration = calibrations[side];
    const range = calibration.ranges[idx];
    const rawVal = isManual ? manualData[side][idx] : rawData[side][idx];
    const processed = side === 'LEFT' ? leftProcessed : rightProcessed;
    const normVal = processed.normalized[idx];

    return (
      <div key={idx} className="mb-3 group bg-gray-900/40 p-2 rounded-lg border border-gray-800/40">
        <div className="flex justify-between text-[11px] mb-1.5 items-center">
          <span className="text-gray-300 font-medium group-hover:text-cyan-200 transition-colors">{label}</span>
          <span className="font-mono text-[9px] text-gray-500 flex gap-2">
             <span className="text-gray-600 w-8 text-right">{rawVal.toFixed(0)}</span>
             <span className="text-gray-700">|</span>
             <span className={`w-8 text-right font-bold ${isManual ? "text-purple-400" : "text-cyan-400"}`}>
               {(normVal * 100).toFixed(0)}%
             </span>
          </span>
        </div>

        {isManual ? (
           <input type="range" min={range.min} max={range.max} value={manualData[side][idx]}
             onChange={(e) => updateManual(idx, parseInt(e.target.value))}
             className="w-full h-1.5 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-500 mb-2" />
        ) : (
          <div className="w-full bg-gray-800 h-1 rounded-full overflow-hidden border border-gray-700/50 mb-2">
            <div className="h-full bg-cyan-500 transition-all duration-200" style={{ width: `${normVal * 100}%` }} />
          </div>
        )}

        <div className="flex items-center gap-2 mt-1 px-1">
           <Zap size={10} className={range.exponent !== 1 ? "text-yellow-500" : "text-gray-600"} />
           <input type="range" min="0.2" max="3.0" step="0.05" value={range.exponent}
             onChange={(e) => updateCurve(idx, parseFloat(e.target.value))}
             className="flex-1 h-1 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-gray-500" />
           <span className="text-[9px] font-mono text-gray-500 w-8 text-right">k={range.exponent.toFixed(1)}</span>
        </div>
      </div>
    );
  };

  const renderDIPControl = (label: string, key: 'index' | 'middle' | 'ring' | 'pinky') => {
    const side = activeSide;
    const isManual = manualMode[side];
    const processed = side === 'LEFT' ? leftProcessed : rightProcessed;
    const val = processed.derived[`${key}DIP` as keyof typeof processed.derived];

    return (
      <div className="mb-2 group bg-gray-900/20 p-2 rounded-lg border border-dashed border-gray-800/40">
        <div className="flex justify-between text-[11px] mb-1 items-center">
          <span className="text-purple-400/80 font-medium group-hover:text-purple-300 transition-colors">{label}</span>
          <span className="font-mono text-[10px] font-bold text-purple-400">{(val * 100).toFixed(0)}%</span>
        </div>
        {isManual ? (
           <input type="range" min="0" max="1" step="0.01" value={manualDIP[side][key]}
             onChange={(e) => {
                setManualDIP(prev => ({ ...prev, [side]: { ...prev[side], [key]: parseFloat(e.target.value) } }));
             }}
             className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
        ) : (
          <div className="w-full bg-gray-800/50 h-1 rounded-full overflow-hidden">
            <div className="h-full bg-purple-500/60" style={{ width: `${val * 100}%` }} />
          </div>
        )}
      </div>
    );
  };

  const getPortLabel = (port: any, index: number) => {
    const info = port.getInfo();
    const vid = info.usbVendorId?.toString(16).padStart(4, '0').toUpperCase();
    const pid = info.usbProductId?.toString(16).padStart(4, '0').toUpperCase();
    return vid ? `Dev ${index + 1} (${vid}:${pid})` : `Serial ${index + 1}`;
  };

  return (
    <div className="h-screen w-screen bg-gray-950 flex flex-col overflow-hidden text-gray-100 font-sans">
      <header className="h-14 border-b border-gray-800 flex items-center justify-between px-4 bg-gray-900/90 backdrop-blur z-50">
        <div className="flex items-center gap-3">
          <Cpu className="w-5 h-5 text-cyan-450" />
          <div className="flex items-baseline gap-2">
            <h1 className="font-bold text-lg tracking-tight text-gray-100">Lyokinn <span className="text-cyan-450">流金智感</span></h1>
            <span className="text-[10px] text-gray-500 font-mono border border-gray-700 px-1.5 rounded">V0.2</span>
          </div>
          <div className={`ml-4 text-[10px] font-bold px-2 py-0.5 rounded uppercase ${connections.LEFT || connections.RIGHT ? 'bg-green-500/20 text-green-400' : 'bg-red-500/20 text-red-400'}`}>
            {connections.LEFT || connections.RIGHT ? '双手已连接' : '未连接设备'}
          </div>
        </div>

        <div className="flex items-center gap-2">
            <div className="flex items-center bg-gray-800/50 rounded-md border border-gray-700/50 p-0.5 group">
                <span className="text-[10px] font-bold px-2 text-gray-500">L</span>
                <select value={selectedPortIndices.LEFT} onChange={(e) => setSelectedPortIndices(p => ({ ...p, LEFT: Number(e.target.value) }))} disabled={connections.LEFT}
                    className="bg-transparent text-[10px] text-gray-400 py-1 pl-1 outline-none max-w-[70px]">
                    {ports.length === 0 && <option value={0}>No Port</option>}
                    {ports.map((p, idx) => (<option key={idx} value={idx}>{getPortLabel(p, idx)}</option>))}
                </select>
                <button onClick={() => handleConnectionToggle('LEFT')} className={`ml-1 px-2 py-1 rounded text-[10px] font-bold border ${connections.LEFT ? 'bg-red-900/30 text-red-400 border-red-800' : 'bg-cyan-600 text-white border-cyan-700'}`}>
                    {connections.LEFT ? 'OFF' : 'ON'}
                </button>
            </div>
            <div className="flex items-center bg-gray-800/50 rounded-md border border-gray-700/50 p-0.5 group">
                <span className="text-[10px] font-bold px-2 text-gray-500">R</span>
                <select value={selectedPortIndices.RIGHT} onChange={(e) => setSelectedPortIndices(p => ({ ...p, RIGHT: Number(e.target.value) }))} disabled={connections.RIGHT}
                    className="bg-transparent text-[10px] text-gray-400 py-1 pl-1 outline-none max-w-[70px]">
                    {ports.length === 0 && <option value={0}>No Port</option>}
                    {ports.map((p, idx) => (<option key={idx} value={idx}>{getPortLabel(p, idx)}</option>))}
                </select>
                <button onClick={() => handleConnectionToggle('RIGHT')} className={`ml-1 px-2 py-1 rounded text-[10px] font-bold border ${connections.RIGHT ? 'bg-red-900/30 text-red-400 border-red-800' : 'bg-purple-600 text-white border-purple-700'}`}>
                    {connections.RIGHT ? 'OFF' : 'ON'}
                </button>
            </div>
            <button onClick={() => setShowPanel(!showPanel)} className={`p-1.5 ml-2 rounded ${showPanel ? 'bg-cyan-900/30 text-cyan-400' : 'bg-gray-800 text-gray-400'}`}><Activity size={18} /></button>
        </div>
      </header>

      <div className="flex-1 flex relative overflow-hidden">
        <div className="flex-1 min-w-0 relative bg-gray-900">
           <Canvas shadows camera={{ position: [0, 2, 12], fov: 40 }}>
             <fog attach="fog" args={['#0d1117', 10, 60]} />
             <ambientLight intensity={1.5} />
             <directionalLight position={[10, 10, 10]} intensity={2.5} castShadow />
             <directionalLight position={[-10, 5, 5]} intensity={1.2} />
             <Environment preset="city" />
             <HandModel data={leftProcessed} side="LEFT" position={[-3.5, -2, 0]} manualOverride={manualMode.LEFT} />
             <HandModel data={rightProcessed} side="RIGHT" position={[3.5, -2, 0]} manualOverride={manualMode.RIGHT} />
             <ContactShadows position={[0, -2, 0]} opacity={0.6} scale={15} blur={1.5} far={4} color="#000000" />
             <Grid args={[40, 40]} cellSize={0.5} cellThickness={0.5} sectionSize={3} fadeDistance={50} sectionColor="#00e5ff" cellColor="#1a202c" position={[0, -2, 0]} />
             <OrbitControls makeDefault minPolarAngle={0} maxPolarAngle={Math.PI / 1.8} />
           </Canvas>

           {calStep !== CalibrationStep.IDLE && (
             <div className="absolute inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                <div className="bg-gray-900 border border-gray-700 p-8 rounded-2xl max-w-md w-full text-center">
                   <RefreshCw className="w-12 h-12 text-cyan-450 animate-spin-slow mx-auto mb-6" />
                   <h2 className="text-2xl font-bold mb-2">传感器标定 [{calTarget === 'BOTH' ? '双侧同时' : (calTarget === 'LEFT' ? '左手' : '右手')}]</h2>
                   <div className="flex justify-center gap-4 mb-4">
                      {(calTarget === 'BOTH' || calTarget === 'LEFT') && <div className={`px-2 py-1 rounded text-[10px] font-bold border ${calBuffers.LEFT.length > 0 ? 'bg-cyan-500/20 text-cyan-400 border-cyan-500/50' : 'bg-gray-800 text-gray-600 border-gray-700'}`}>LEFT READY</div>}
                      {(calTarget === 'BOTH' || calTarget === 'RIGHT') && <div className={`px-2 py-1 rounded text-[10px] font-bold border ${calBuffers.RIGHT.length > 0 ? 'bg-purple-500/20 text-purple-400 border-purple-500/50' : 'bg-gray-800 text-gray-600 border-gray-700'}`}>RIGHT READY</div>}
                   </div>
                   <p className="text-gray-400 mb-8 text-sm h-12">
                     {calStep === CalibrationStep.FIST && `步骤 1：用力握紧${calTarget === 'BOTH' ? '双手' : ''}拳头，并保持稳定。`}
                     {calStep === CalibrationStep.FLAT && `步骤 2：将${calTarget === 'BOTH' ? '双手' : ''}手掌平放，五指并拢伸直。`}
                     {calStep === CalibrationStep.SPREAD && `步骤 3：尽力张开${calTarget === 'BOTH' ? '双手' : ''}大拇指和四指。`}
                   </p>
                   <div className="flex gap-3 justify-center">
                      <button onClick={() => setCalStep(CalibrationStep.IDLE)} className="px-6 py-2.5 rounded-lg bg-gray-800 text-gray-300 text-sm border border-gray-700">取消</button>
                      <button onClick={nextCalibrationStep} className="px-8 py-2.5 rounded-lg bg-cyan-600 text-white font-bold text-sm">{calStep === CalibrationStep.SPREAD ? '完成标定' : '下一步'}</button>
                   </div>
                </div>
             </div>
           )}
        </div>

        {showPanel && (
          <div className="w-80 md:w-96 bg-gray-900 border-l border-gray-800 flex flex-col h-full z-20 shadow-2xl overflow-hidden">
            {/* Hand Tabs */}
            <div className="flex bg-gray-950 p-1">
                <button onClick={() => setActiveSide('LEFT')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-xs font-bold transition-all rounded-t-lg ${activeSide === 'LEFT' ? 'bg-gray-900 text-cyan-400 border-t-2 border-cyan-500' : 'text-gray-600'}`}><ArrowLeftRight size={14} /> LEFT</button>
                <button onClick={() => setActiveSide('RIGHT')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-xs font-bold transition-all rounded-t-lg ${activeSide === 'RIGHT' ? 'bg-gray-900 text-purple-400 border-t-2 border-purple-500' : 'text-gray-600'}`}>RIGHT <ArrowLeftRight size={14} /></button>
            </div>

            {/* Global Modes */}
            <div className="p-4 border-b border-gray-800 flex items-center justify-between bg-gray-900/50">
               <span className="text-[10px] font-bold uppercase text-gray-500 flex items-center gap-2"><Sliders size={14} /> 控制模式</span>
               <div className="flex bg-gray-800 rounded-md p-1 border border-gray-700">
                  <button onClick={() => setManualMode(prev => ({ ...prev, [activeSide]: false }))} className={`px-3 py-1 text-[10px] font-bold rounded ${!manualMode[activeSide] ? 'bg-cyan-600 text-white' : 'text-gray-400'}`}>传感器</button>
                  <button onClick={() => setManualMode(prev => ({ ...prev, [activeSide]: true }))} className={`px-3 py-1 text-[10px] font-bold rounded ${manualMode[activeSide] ? 'bg-purple-600 text-white' : 'text-gray-400'}`}>手动</button>
               </div>
            </div>

            {/* Calibration & Quick Info */}
            <div className="px-4 py-3 bg-cyan-500/5 border-b border-gray-800 flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${calibrations[activeSide].isCalibrated ? 'bg-green-500 animate-pulse' : 'bg-orange-500'}`} />
                    <span className="text-[10px] font-bold text-gray-400 uppercase">
                        {calibrations[activeSide].isCalibrated ? '已标定' : '未标定'}
                    </span>
                </div>
                <button onClick={() => startCalibration(activeSide)} className="text-[9px] uppercase font-bold text-cyan-400 hover:text-cyan-300 transition-colors bg-cyan-400/10 px-2 py-1 rounded border border-cyan-400/20">重新标定</button>
            </div>

            {/* Finger Groups */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4">
               {/* 1. THUMB */}
               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800 flex items-center gap-2">
                    <span className={`w-2 h-2 rounded-full ${activeSide === 'LEFT' ? 'bg-cyan-500' : 'bg-purple-500'}`}></span>
                    <h3 className="text-[10px] font-bold text-gray-300 uppercase">大拇指 Thumb</h3>
                  </div>
                  <div className="p-3">
                    {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.THUMB_MCP)}
                    {renderSensorControl("指间关节 (IP)", SENSOR_MAP.THUMB_IP)}
                    {renderSensorControl("虎口张开 (Spread)", SENSOR_MAP.THUMB_SPREAD)}
                  </div>
               </div>

               {/* 2. INDEX */}
               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800">
                    <h3 className="text-[10px] font-bold text-gray-300 uppercase">食指 Index</h3>
                  </div>
                  <div className="p-3">
                    {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.INDEX_MCP)}
                    {renderSensorControl("近端指间关节 (PIP)", SENSOR_MAP.INDEX_PIP)}
                    {renderDIPControl("远端指间关节 (DIP)", "index")}
                  </div>
               </div>

               {/* 3. MIDDLE */}
               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800">
                    <h3 className="text-[10px] font-bold text-gray-300 uppercase">中指 Middle</h3>
                  </div>
                  <div className="p-3">
                    {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.MIDDLE_MCP)}
                    {renderSensorControl("近端指间关节 (PIP)", SENSOR_MAP.MIDDLE_PIP)}
                    {renderDIPControl("远端指间关节 (DIP)", "middle")}
                  </div>
               </div>

               {/* 4. RING */}
               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800">
                    <h3 className="text-[10px] font-bold text-gray-300 uppercase">无名指 Ring</h3>
                  </div>
                  <div className="p-3">
                    {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.RING_MCP)}
                    {renderSensorControl("近端指间关节 (PIP)", SENSOR_MAP.RING_PIP)}
                    {renderDIPControl("远端指间关节 (DIP)", "ring")}
                  </div>
               </div>

               {/* 5. PINKY */}
               <div className="bg-gray-800/20 rounded-xl border border-gray-800 overflow-hidden">
                  <div className="px-4 py-2 bg-gray-800/50 border-b border-gray-800">
                    <h3 className="text-[10px] font-bold text-gray-300 uppercase">小指 Pinky</h3>
                  </div>
                  <div className="p-3">
                    {renderSensorControl("掌指关节 (MCP)", SENSOR_MAP.PINKY_MCP)}
                    {renderSensorControl("近端指间关节 (PIP)", SENSOR_MAP.PINKY_PIP)}
                    {renderDIPControl("远端指间关节 (DIP)", "pinky")}
                  </div>
               </div>

               {/* Global Calibration Action */}
               <div className="rounded-xl p-4 border border-dashed border-gray-700/50 bg-gray-900/50 flex flex-col gap-3">
                  <div className="flex items-center gap-2 text-[10px] text-gray-500">
                     <Info size={14} className="text-cyan-400" />
                     <span>需要同时校准两只手？</span>
                  </div>
                  <button 
                    onClick={() => startCalibration('BOTH')} 
                    disabled={!connections.LEFT || !connections.RIGHT}
                    className="w-full py-2.5 text-[10px] uppercase font-bold rounded-lg bg-gray-800 text-gray-300 border border-gray-700 hover:bg-gray-700 transition-colors disabled:opacity-20">
                    双手同步标定
                  </button>
               </div>
            </div>

            {/* Footer Status */}
            <div className="px-4 py-2 border-t border-gray-800 bg-gray-950 text-[9px] text-gray-600 flex justify-between items-center">
                <span className="flex items-center gap-1"><RefreshCw size={10} /> 11ch @ 115200</span>
                <span className="font-mono text-cyan-800 uppercase">{activeSide} HAND ACTIVE</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
